-- Activity Centre: seed the authored Activity library.
--
-- Places four authored Activities into public.activities so they are
-- assignable from the teacher library and reach students through the Activity
-- Centre. Content is generated from the item banks in the vault
-- (~/ai-os/brainstorms/2026-08-03-*-bank.md) and mirrored, typed and tested, at
-- src/features/activity-centre/content/.
--
--   find-the-conclusion    Find the Conclusion       62 items
--   conditional-rephrase   Conditional Rephrase      62 items
--   rebuttal-rephrase      Rebuttal Rephrase         42 items
--   dumb-it-down           Dumb it Down              24 items
--                                                   190 items total
--
-- Negation Station is deliberately untouched: it already exists and its items
-- are authored verbatim. Its instructions carry no `coach` block, so the
-- activity-coach function keeps applying its original negation rubric.
--
-- Ownership: activities.created_by must be a real admin and RLS scopes reads to
-- created_by = auth.uid(), so each row is attached to the first admin account.
-- The profiles.class_id = user_id invariant gives class_id. If no admin exists
-- the insert is a no-op rather than an error, and re-running after one is
-- created will seed correctly.
--
-- Idempotent: re-running refreshes title/subtitle/instructions/items in place
-- on the slug conflict. Existing activity_assignments are snapshots and are
-- intentionally NOT rewritten; a student mid-Activity keeps what they started.

DO $$
DECLARE
  admin_id uuid;
  admin_class uuid;
BEGIN
  SELECT ur.user_id INTO admin_id
  FROM public.user_roles ur
  WHERE ur.role = 'admin'
  ORDER BY ur.user_id
  LIMIT 1;

  IF admin_id IS NULL THEN
    RAISE NOTICE 'seed_activity_library: no admin account found, skipping seed';
    RETURN;
  END IF;

  SELECT p.class_id INTO admin_class FROM public.profiles p WHERE p.id = admin_id;
  IF admin_class IS NULL THEN
    admin_class := admin_id;  -- profiles.class_id = user_id invariant
  END IF;

  INSERT INTO public.activities
    (slug, title, subtitle, instructions, item_format, items, created_by, class_id)
  SELECT s.slug, s.title, s.subtitle, s.instructions, s.item_format, s.items, admin_id, admin_class
  FROM (VALUES
  (
    'find-the-conclusion',
    'Find the Conclusion',
    'Name the claim the argument is trying to prove',
    '{"coach": {"drill": "a main-conclusion identification drill: the student reads an argument and names the claim the author is trying to prove", "rubric": ["The credited answer is the argument''s main conclusion. Accept any accurate paraphrase as readily as a direct quote; students are told to answer in their own words.", "Apply the 2-Point Check: a conclusion sounds like the author''s opinion (facts are not conclusions) and is supported by at least one other explicit claim in the argument.", "The conclusion is usually NOT the last sentence. Do not reward a response just because it quotes the closing line.", "If the argument''s stated conclusion uses referential language (this position, such a rule, they are wrong), a response that writes the reference back in is correct, and one that leaves the pronoun unresolved is at best partial."], "partial_rule": "Mark ''partial'' when the student names an INTERMEDIATE conclusion (a claim that is supported but is itself there to support the main one), or names the right claim but drops a qualifier that changes its scope or strength (an ''even if'', a comparison, a time limit). Mark ''incorrect'' when they give a premise, the opposing view the author is arguing against, background framing, or a claim the author would agree with but never argues for."}, "tagline": "The conclusion is rarely the last thing you read.", "task": "Read the argument and tell me, in your own words or as a direct quote, the main conclusion. Then I will tell you what I see.", "rules": ["Run the 2-Point Check on any claim you are considering. Does it sound like the author''s opinion? Facts are not conclusions. And is it supported by at least one other claim in the argument?", "More than nine times out of ten the conclusion comes before its support. Look at the first sentence, and look at the claim right after a But, Yet, or However.", "FABS marks evidence: for, after all, because, since. Whatever follows one of those is support, so the claim in front of it is usually the point.", "If the conclusion is a pronoun sentence (this position, such a rule, they are wrong), write the reference back in before you say it.", "Point at your candidate and ask, why should we believe that? If the rest of the argument answers you, you have found it."], "worked_example": {"statement": "Some critics say the reading room should stay open past midnight. But the security desk closes at eleven, and an unstaffed room with open stacks is how the last three thefts happened. Extended hours are not worth the risk to the collection.", "credited_answers": ["Extended hours are not worth the risk to the collection."], "explanation": "The attribution comes first, the pivot at But turns to the author, and the last sentence is the claim the theft history is there to support. The critics'' proposal is somebody else''s view, and the thefts are evidence."}}'::jsonb,
    'free-text',
    '[{"order": 1, "prompt": "The city''s bike-share docks sit full every weekday morning. Ridership logs show almost no trips beginning before ten. Therefore the program''s early-commuter goal has not been met.", "credited_answers": ["The program''s early-commuter goal has not been met."], "explanation": "Wrong turn: \"Almost no trips begin before ten\" (premise). \"Therefore,\" final seat. Baseline. Note: the clean case, so the student can feel the shape before it gets hidden.", "category": "Level 1: Basic conclusion indicator"}, {"order": 2, "prompt": "So the archive should digitize the glass negatives before the paper files. The negatives are deteriorating faster and a single loss is unrecoverable, while the paper files are stable in current storage.", "credited_answers": ["The archive should digitize the glass negatives before the paper files."], "explanation": "Wrong turn: \"The negatives are deteriorating faster\" (premise). \"So\" opening plus \"should,\" initial seat. Baseline. Note: a conclusion indicator can open an argument. Position is not the tell; support is.", "category": "Level 1: Basic conclusion indicator"}, {"order": 3, "prompt": "Attendance at the lunchtime lecture series has fallen for six straight terms. The room runs half empty even for invited speakers. It follows that the series in its current form no longer earns the room booking.", "credited_answers": ["The series in its current form no longer earns the room booking."], "explanation": "Wrong turn: the attendance fact. \"It follows that,\" final seat. Baseline.", "category": "Level 1: Basic conclusion indicator"}, {"order": 4, "prompt": "Consequently the co-op should stock the smaller flour sacks. Members living alone report throwing out spoiled flour, and the twenty-pound sack is the only size on the shelf.", "credited_answers": ["The co-op should stock the smaller flour sacks."], "explanation": "Wrong turn: \"the twenty-pound sack is the only size\" (premise). \"Consequently\" opening. Baseline.", "category": "Level 1: Basic conclusion indicator"}, {"order": 5, "prompt": "Hospital records show the revised triage script cut average wait time by eleven minutes. Complaints about waiting dropped over the same period. Thus the script is doing what it was written to do.", "credited_answers": ["The script is doing what it was written to do."], "explanation": "Wrong turn: the eleven-minute figure. \"Thus,\" final seat. Baseline.", "category": "Level 1: Basic conclusion indicator"}, {"order": 6, "prompt": "This shows that the vineyard''s frost fans are earning their cost. Rows inside the fan radius lost four percent of buds in the April freeze. Unprotected rows lost nineteen.", "credited_answers": ["The frost fans are earning their cost."], "explanation": "Wrong turn: either bud-loss figure. \"This shows that,\" initial seat. Baseline. Note: \"This shows that\" usually marks an intermediate conclusion at Level 4. Here it marks the main one. The phrase is a clue, never a verdict.", "category": "Level 1: Basic conclusion indicator"}, {"order": 7, "prompt": "The translation committee has met eleven times without producing a chapter. Two members have not attended since spring. As a result the committee cannot deliver the manuscript on the promised schedule.", "credited_answers": ["The committee cannot deliver the manuscript on the promised schedule."], "explanation": "Wrong turn: the attendance fact. \"As a result,\" final seat. Baseline.", "category": "Level 1: Basic conclusion indicator"}, {"order": 8, "prompt": "Hence the museum''s audio guide needs rewriting. Visitors surveyed at the exit could not recall a single fact from it, and the guide has not been revised since the collection was rehung.", "credited_answers": ["The audio guide needs rewriting."], "explanation": "Wrong turn: the survey result. \"Hence,\" initial seat. Baseline.", "category": "Level 1: Basic conclusion indicator"}, {"order": 9, "prompt": "Every trailhead sign in the park was replaced last season. Rangers report a sharp drop in calls from lost hikers. We can conclude that the new signs are doing their job.", "credited_answers": ["The new signs are doing their job."], "explanation": "Wrong turn: the drop in calls. \"We can conclude,\" final seat. Baseline.", "category": "Level 1: Basic conclusion indicator"}, {"order": 10, "prompt": "The press should keep the hardcover in print. Libraries continue to order it, the paperback has not displaced those orders, and the plates are already paid for. So the print run should be renewed on the current schedule.", "credited_answers": ["The press should keep the hardcover in print."], "explanation": "Near miss (partial): \"the print run should be renewed on the current schedule\" (the closing sentence restates the opening claim; crediting it is acceptable, but a student who picks it because it carries \"So\" has used the wrong reason). Wrong turn: \"the plates are already paid for.\" \"So,\" final seat, with the real claim opening. Trait 1 preview. Note: first sighting of the Last Claim Trap in a friendly setting.", "category": "Level 1: Basic conclusion indicator"}, {"order": 11, "prompt": "The apprenticeship should be extended to a second year. After all, first-year apprentices still need supervision on every complex repair, and the shop cannot bill their hours at full rate.", "credited_answers": ["The apprenticeship should be extended to a second year."], "explanation": "Wrong turn: either supervision or billing fact. \"After all,\" support. Trait 3. Note: \"After all\" is the purest FABS marker. Nothing after it is ever the conclusion.", "category": "Level 2: Conclusion before a support indicator (FABS)"}, {"order": 12, "prompt": "The lab''s freezer alarm is inadequate, since it pages one technician and gives no second alert if that page goes unanswered.", "credited_answers": ["The freezer alarm is inadequate."], "explanation": "Wrong turn: the paging description. \"Since,\" support. Trait 3.", "category": "Level 2: Conclusion before a support indicator (FABS)"}, {"order": 13, "prompt": "The island grocery now runs short by Thursday because the ferry schedule was cut to two crossings. The store cannot restock between crossings, and Thursday is when weekend demand begins.", "credited_answers": ["The grocery runs short by Thursday because the ferry schedule was cut."], "explanation": "Near miss (partial): \"the grocery runs short by Thursday\" with the cause dropped (scope loss: the claim is causal). Wrong turn: \"the store cannot restock between crossings.\" \"Because,\" support. Trait 4. Note: when the conclusion is causal, an answer that keeps only the effect is a scope drop.", "category": "Level 2: Conclusion before a support indicator (FABS)"}, {"order": 14, "prompt": "Reviewers should be paid for their time. For the journal now waits five months on average for a report, and unpaid work is the first thing a busy academic drops.", "credited_answers": ["Reviewers should be paid for their time."], "explanation": "Wrong turn: the five-month figure. \"For,\" support. Trait 3. Note: sentence-initial \"For\" reads as archaic to students and gets misread as a preposition. Worth one Coach line.", "category": "Level 2: Conclusion before a support indicator (FABS)"}, {"order": 15, "prompt": "The removable resin is the better choice for this restoration, since it comes off with a solvent that does not touch the original pigment.", "credited_answers": ["The removable resin is the better choice for this restoration."], "explanation": "Near miss (partial): \"the resin is the better choice\" with \"for this restoration\" dropped. \"Since,\" support. Trait 4.", "category": "Level 2: Conclusion before a support indicator (FABS)"}, {"order": 16, "prompt": "Digitizing the oral histories is more urgent than cataloguing them, because the tapes shed oxide with every playback while the catalogue can be built from a digital copy at any time.", "credited_answers": ["Digitizing is more urgent than cataloguing."], "explanation": "Near miss (partial): \"digitizing is urgent\" (drops the comparison, which is the whole claim). \"Because,\" support. Trait 4. Note: comparative conclusions lose their meaning the moment the comparison is trimmed.", "category": "Level 2: Conclusion before a support indicator (FABS)"}, {"order": 17, "prompt": "The second bakery will not break even this year. After all, it opened in March, its lease is nearly double the original shop''s, and the neighborhood empties out in summer.", "credited_answers": ["The second bakery will not break even this year."], "explanation": "Wrong turn: the lease fact. \"After all,\" support. Trait 5. Note: an answer saying the second location was a mistake is agreeable and not the claim.", "category": "Level 2: Conclusion before a support indicator (FABS)"}, {"order": 18, "prompt": "The council''s parking study is unreliable, for the counts were taken during the two weeks the arena was closed for repairs.", "credited_answers": ["The parking study is unreliable."], "explanation": "Wrong turn: the closure fact. \"For,\" support. Trait 3.", "category": "Level 2: Conclusion before a support indicator (FABS)"}, {"order": 19, "prompt": "Students learn the citation rules faster by marking up a flawed bibliography than by reading the style guide, since correcting an error forces them to name the rule it breaks.", "credited_answers": ["The comparative claim about the two methods."], "explanation": "Near miss (partial): \"marking up a flawed bibliography teaches citation rules\" (comparison dropped). \"Since,\" support. Trait 4.", "category": "Level 2: Conclusion before a support indicator (FABS)"}, {"order": 20, "prompt": "The orchard should replace its older pollinator hives this winter, because a fifth-season hive produces roughly half the foraging activity of a second-season hive, and the bloom window is too short to make up the difference.", "credited_answers": ["The orchard should replace its older hives this winter."], "explanation": "Near miss (partial): \"older hives forage less\" (that is the premise doing the work). \"Because,\" support. Trait 3.", "category": "Level 2: Conclusion before a support indicator (FABS)"}, {"order": 21, "prompt": "It is not worth resurfacing the north court this year. After all, the surface is worn but still playable, and the crew charges a premium before June.", "credited_answers": ["It is not worth resurfacing the north court this year."], "explanation": "Near miss (partial): \"the court does not need resurfacing\" (drops \"this year,\" which is the qualification carrying the claim). \"After all,\" support. Trait 4.", "category": "Level 2: Conclusion before a support indicator (FABS)"}, {"order": 22, "prompt": "The revised intake form is an improvement, since the field that most often went blank has been split into two shorter questions and now gets answered.", "credited_answers": ["The revised intake form is an improvement."], "explanation": "Wrong turn: the split-field description. \"Since,\" support. Trait 3.", "category": "Level 2: Conclusion before a support indicator (FABS)"}, {"order": 23, "prompt": "Some curators maintain that rotating the textiles every three months keeps any single piece from fading. But the handling is what damages the fibers. Each rotation means two mountings and two dismountings, and conservators have logged more thread loss from handling than from light.", "credited_answers": ["The handling is what damages the fibers."], "explanation": "Near miss (partial): the thread-loss comparison (support). Wrong turn: the curators'' rotation claim (opposing view). \"Some curators maintain\" attribution, \"But\" pivot. Trait 3.", "category": "Level 3: Pivot from an opposing view"}, {"order": 24, "prompt": "It is commonly believed that a longer warranty signals a more durable product. However, warranty length is set by the finance department, not by the engineers. Two of the company''s shortest-lived models carry its longest warranties.", "credited_answers": ["Warranty length is set by finance, not engineering (therefore it does not signal durability). Credit either the stated pivot claim or the unpacked version."], "explanation": "Wrong turn: the common belief. \"It''s commonly believed\" attribution, \"However\" pivot. Trait 3.", "category": "Level 3: Pivot from an opposing view"}, {"order": 25, "prompt": "Some economists argue that the vacancy tax will bring rents down. Yet the tax applies only to units empty more than a year, and the units driving the increase turn over every few months.", "credited_answers": ["The vacancy tax will not bring rents down (the pivot claim, unpacked)."], "explanation": "Near miss (partial): \"the tax applies only to units empty more than a year\" left as-is without drawing the point. Wrong turn: the economists'' claim. \"Yet\" pivot. Trait 2 blend. Note: the pivot sentence here is evidence for a conclusion the author leaves implicit. Flagged deliberately.", "category": "Level 3: Pivot from an opposing view"}, {"order": 26, "prompt": "Trainers often say the taper week before a race is optional for recreational runners. That advice is probably wrong. Recreational runners accumulate the same relative fatigue as competitive ones and have less recovery capacity to absorb it.", "credited_answers": ["(substituted): The taper week is not optional for recreational runners."], "explanation": "Near miss (partial): \"that advice is probably wrong\" left referential. Wrong turn: the trainers'' advice. \"Often say\" attribution, \"probably\" opinion indicator. Trait 3 plus referential substitution. Note: the explicit conclusion is a pronoun sentence. Write the reference back in.", "category": "Level 3: Pivot from an opposing view"}, {"order": 27, "prompt": "Several reviewers have written that the novel''s second half loses focus. But the shift they describe is the point. The narrator''s account fragments precisely as her memory does, and every apparent digression returns in the final chapter.", "credited_answers": ["The shift the reviewers describe is deliberate, not a loss of focus."], "explanation": "Near miss (partial): \"the digressions return in the final chapter\" (support). Wrong turn: the reviewers'' complaint. \"But\" pivot. Trait 3.", "category": "Level 3: Pivot from an opposing view"}, {"order": 28, "prompt": "The received view is that the fort was abandoned after the flood. However, the abandonment layer sits below the flood silt, not above it. Whatever emptied the fort happened first.", "credited_answers": ["Whatever emptied the fort happened before the flood."], "explanation": "Near miss (partial): the stratigraphy fact (this is the pivot sentence, and it is evidence). Wrong turn: the received view. \"However\" pivot carrying evidence, conclusion in the final seat. Trait 7 cousin. Note: designed counterexample. The pivot marks where the author turns, not always what the author concludes. Run the 2-Point Check.", "category": "Level 3: Pivot from an opposing view"}, {"order": 29, "prompt": "Many gardeners insist that autumn mulching protects perennials through winter. But mulch laid before the ground freezes keeps the soil warm enough for voles to tunnel, and vole damage costs more crowns than frost does.", "credited_answers": ["Autumn mulching does not protect perennials as claimed (the pivot claim, unpacked)."], "explanation": "Wrong turn: the gardeners'' claim. \"But\" pivot. Trait 2 blend.", "category": "Level 3: Pivot from an opposing view"}, {"order": 30, "prompt": "Administrators have claimed the new scheduling software saves staff time. It clearly does not. The software removed the paper roster but added a daily reconciliation step that takes longer than the roster ever did.", "credited_answers": ["(substituted): The new scheduling software does not save staff time."], "explanation": "Near miss (partial): \"it clearly does not\" left referential. Wrong turn: the administrators'' claim. \"Clearly\" opinion indicator. Trait 3 plus referential substitution.", "category": "Level 3: Pivot from an opposing view"}, {"order": 31, "prompt": "Some readers hold that footnotes interrupt a narrative history. Granted, a dense note can pull a reader out of a scene. Even so, a history without notes asks the reader to take every claim on trust, and that is the worse interruption.", "credited_answers": ["A history without notes is the worse interruption."], "explanation": "Near miss (partial): the concession (\"a dense note can pull a reader out of a scene\"). Wrong turn: the readers'' position. \"Granted\" concession, \"Even so\" pivot. Trait 5. Note: the concession is engineered to sound balanced and reasonable. It is not the point.", "category": "Level 3: Pivot from an opposing view"}, {"order": 32, "prompt": "Critics of the ferry subsidy say it benefits only weekend visitors. However, the ridership data separate residents from visitors, and residents account for two-thirds of subsidized trips. The subsidy is primarily a resident service.", "credited_answers": ["The subsidy is primarily a resident service."], "explanation": "Near miss (partial): the two-thirds figure. Wrong turn: the critics'' claim. \"However\" pivot carrying evidence, conclusion final. Trait 7 cousin. Note: second designed counterexample, paired with item 28.", "category": "Level 3: Pivot from an opposing view"}, {"order": 33, "prompt": "Prevailing opinion treats the anonymous letters as forgeries. Yet the paper stock matches the mill''s records for those years, and the watermark could not have been reproduced with period equipment. The letters are almost certainly genuine.", "credited_answers": ["The letters are almost certainly genuine."], "explanation": "Near miss (partial): \"the letters are genuine\" (drops \"almost certainly\"). Wrong turn: the prevailing opinion. \"Yet\" pivot, conclusion final with a hedge. Trait 4.", "category": "Level 3: Pivot from an opposing view"}, {"order": 34, "prompt": "Some argue the reading room should stay open past midnight. But the security desk closes at eleven, and an unstaffed room with open stacks is how the last three thefts happened. Extended hours are not worth the risk to the collection.", "credited_answers": ["Extended hours are not worth the risk to the collection."], "explanation": "Near miss (partial): the theft history. Wrong turn: the proposal being rejected. \"But\" pivot, conclusion final. Trait 5.", "category": "Level 3: Pivot from an opposing view"}, {"order": 35, "prompt": "It is often said that a small press cannot compete for prizes. This is not so. Three of the last five poetry awards went to presses with fewer than four employees.", "credited_answers": ["(substituted): A small press can compete for prizes."], "explanation": "Near miss (partial): \"this is not so\" left referential; also \"small presses win most poetry awards\" (overshoot). Wrong turn: the award statistic. \"It is often said\" attribution, bare referential rejection. Trait 4 plus substitution. Note: the closest item in this bank to Rebuttal Rephrase. Same anatomy, different task: here you name the conclusion, there you rewrite it.", "category": "Level 3: Pivot from an opposing view"}, {"order": 36, "prompt": "Some historians argue the guild records understate apprentice numbers. But the records were kept for tax purposes, and the tax fell on masters rather than apprentices, so the guild had no reason to undercount them.", "credited_answers": ["The guild had no reason to undercount apprentices."], "explanation": "Near miss (partial): \"the tax fell on masters\" (support). Wrong turn: the historians'' claim. \"But\" pivot plus \"so.\" Trait 3.", "category": "Level 3: Pivot from an opposing view"}, {"order": 37, "prompt": "The bindery''s new adhesive holds a text block through three thousand open-and-close cycles. The old adhesive failed at eight hundred. This shows the new adhesive is substantially more durable. Therefore the library should specify it for all rebinding going forward.", "credited_answers": ["The library should specify the new adhesive for all rebinding."], "explanation": "Near miss (partial): \"the new adhesive is substantially more durable\" (intermediate). Wrong turn: the cycle counts. \"This shows that\" then \"Therefore.\" Trait 7 baseline. Note: two indicators, two claims. The one that supports the other is the intermediate.", "category": "Level 4: Intermediate versus main conclusion"}, {"order": 38, "prompt": "Enrollment in the evening section has doubled while the morning section has shrunk. Thus students prefer the evening slot. The department should move the second lecture to the evening as well.", "credited_answers": ["The department should move the second lecture to the evening."], "explanation": "Near miss (partial): \"students prefer the evening slot\" (intermediate, and it carries the \"Thus\"). Wrong turn: the enrollment figures. Unmarked final conclusion. Trait 7.", "category": "Level 4: Intermediate versus main conclusion"}, {"order": 39, "prompt": "Every batch that failed inspection last quarter came from the same mixing line. That line has not been recalibrated since installation. So the calibration schedule, not the operators, explains the failures. The plant should recalibrate before assigning any retraining.", "credited_answers": ["The plant should recalibrate before assigning retraining."], "explanation": "Near miss (partial): \"the calibration schedule explains the failures\" (intermediate). Wrong turn: the same-line fact. \"So\" on the intermediate. Trait 7.", "category": "Level 4: Intermediate versus main conclusion"}, {"order": 40, "prompt": "Rooftop sensors record surface temperatures twenty degrees higher on tar roofs than on planted roofs. Planted roofs cost more to install but need no cooling equipment on the floors below. The city''s roof-replacement grant should favor planted roofs. Thus a building that switches will draw less power on the hottest afternoons of the year.", "credited_answers": ["The grant should favor planted roofs."], "explanation": "Near miss (partial): the closing \"Thus\" sentence (a downstream consequence, not the point). Wrong turn: the temperature reading. \"Thus\" in the final seat on a non-conclusion. Trait 7 inverted. Note: this is the trap his part 2 names outright. A mechanical reader takes the \"thus\" sentence every time.", "category": "Level 4: Intermediate versus main conclusion"}, {"order": 41, "prompt": "The new bus route carries three times the riders the planners forecast. This shows the forecast model underestimates demand on cross-town corridors. The agency should re-run its projections for the two remaining corridors before setting their schedules.", "credited_answers": ["The agency should re-run its projections before setting schedules."], "explanation": "Near miss (partial): \"the model underestimates cross-town demand\" (intermediate). \"This shows that.\" Trait 7.", "category": "Level 4: Intermediate versus main conclusion"}, {"order": 42, "prompt": "Wheat sown after the first hard frost germinated at less than half the rate of wheat sown two weeks earlier. Thus the planting window is narrower than the almanac suggests. Growers who wait for the almanac date are losing yield they could keep by sowing early.", "credited_answers": ["Growers who wait for the almanac date are losing yield."], "explanation": "Near miss (partial): \"the planting window is narrower than the almanac suggests\" (intermediate). \"Thus\" on the intermediate. Trait 7.", "category": "Level 4: Intermediate versus main conclusion"}, {"order": 43, "prompt": "Since the clinic began calling patients the day before an appointment, no-shows have fallen by a third. This demonstrates the reminder call works. The clinic should extend the calls to its satellite location, where the no-show rate is higher still.", "credited_answers": ["The clinic should extend the calls to the satellite location."], "explanation": "Near miss (partial): \"the reminder call works\" (intermediate). Wrong turn: the one-third figure. \"Since\" opening a premise, \"This demonstrates\" on the intermediate. Trait 7. Note: \"Since\" here is temporal, not FABS. Worth a Coach line.", "category": "Level 4: Intermediate versus main conclusion"}, {"order": 44, "prompt": "The recording made in the stone chapel has a reverberation tail nearly four seconds long. Thus the chapel is acoustically unsuitable for spoken word. The society should book the rehearsal hall for the audiobook sessions and keep the chapel for choral work.", "credited_answers": ["The society should book the rehearsal hall for audiobooks and keep the chapel for choral work."], "explanation": "Near miss (partial): \"the chapel is unsuitable for spoken word\" (intermediate); also the recommendation with only half its content (scope drop). Trait 4 plus Trait 7.", "category": "Level 4: Intermediate versus main conclusion"}, {"order": 45, "prompt": "Sea ice around the inlet breaks up eleven days earlier than it did thirty years ago. Seals rely on stable ice for pupping, and the pups are not weaned when the ice goes. The inlet''s seal population is unlikely to recover without a change in ice conditions. Thus the operators who advertise reliable seal sightings will disappoint their customers more often each year.", "credited_answers": ["The seal population is unlikely to recover without a change in ice conditions."], "explanation": "Near miss (partial): the closing \"Thus\" sentence (consequence). Wrong turn: the weaning fact. Trait 7 inverted.", "category": "Level 4: Intermediate versus main conclusion"}, {"order": 46, "prompt": "Applications rose the year the fee was waived and fell the year it returned. This suggests the fee, not the program''s reputation, drives application volume. The admissions office should treat the fee as a policy lever rather than a revenue line.", "credited_answers": ["The office should treat the fee as a policy lever rather than a revenue line."], "explanation": "Near miss (partial): \"the fee drives application volume\" (intermediate). Trait 7.", "category": "Level 4: Intermediate versus main conclusion"}, {"order": 47, "prompt": "Two independent labs dated the timber to within five years of each other. So the construction date is now well established. The gallery''s wall text, which still gives a range of two centuries, needs replacing.", "credited_answers": ["The wall text needs replacing."], "explanation": "Near miss (partial): \"the construction date is well established\" (intermediate). \"So\" on the intermediate. Trait 7.", "category": "Level 4: Intermediate versus main conclusion"}, {"order": 48, "prompt": "The pump station has failed twice during storms and never in dry weather. This points to the storm drain intake rather than the pump motor as the source. Replacing the motor a third time would not address the problem.", "credited_answers": ["Replacing the motor a third time would not address the problem."], "explanation": "Near miss (partial): \"the intake is the source\" (intermediate). Wrong turn: the failure pattern. Trait 7.", "category": "Level 4: Intermediate versus main conclusion"}, {"order": 49, "prompt": "The board''s decision to sell the water rights before commissioning a hydrology study was indefensible. The study would have taken four months. The buyer''s offer was open for a year. Nothing about the timeline required acting first and learning later.", "credited_answers": ["The decision to sell before commissioning the study was indefensible."], "explanation": "Near miss (partial): \"the board should have commissioned the study first\" (close, but drops the evaluative force the argument is defending). Wrong turn: the four-month figure. No indicator; evaluative word \"indefensible\" in the first seat. Trait 1 and Trait 4. Note: with no indicator anywhere, the evaluative word is the tell, and the last three sentences answer \"Why should we believe that?\"", "category": "Level 5: No clean indicator, unstated, qualified, or somebody else''s conclusion"}, {"order": 50, "prompt": "The orchestra''s committee argues that screened auditions eliminate bias and that this alone settles the question. Screens do remove one kind of bias. But the repertoire list is set before the screen goes up, and that list favors the training available at a few conservatories. Even if the screen works exactly as intended, it cannot correct a bias that operates before anyone plays.", "credited_answers": ["Even if the screen works as intended, it cannot correct a bias operating before anyone plays."], "explanation": "Near miss (partial): \"screened auditions do not eliminate bias\" (drops the \"even if,\" which is the author''s careful concession). Wrong turn: \"screens do remove one kind of bias\" (concession) or the committee''s position. Outside party''s conclusion, author''s objection, qualified main conclusion. Trait 4 and Trait 5. Note: the hardest shape in his taxonomy. The qualification is not decoration; removing it makes a claim the author declined to make.", "category": "Level 5: No clean indicator, unstated, qualified, or somebody else''s conclusion"}, {"order": 51, "prompt": "No manuscript enters the conservation queue without a condition report. Condition reports are written only by staff conservators. Both staff conservators have been on leave since January, and no reports have been filed since.", "credited_answers": ["(derived): No manuscript has entered the conservation queue since January."], "explanation": "Near miss (partial): \"no condition reports have been filed since January\" (a link in the chain, not its end). Wrong turn: any single premise. No conclusion stated at all. Trait 2. Note: connect the chain, then say what has to be true if every premise is.", "category": "Level 5: No clean indicator, unstated, qualified, or somebody else''s conclusion"}, {"order": 52, "prompt": "Any exhibit that travels must be crated to the lender''s specification. The lender specifies a climate-controlled crate for anything on panel. The altarpiece is on panel and is scheduled to travel in March.", "credited_answers": ["(derived): The altarpiece must be crated in a climate-controlled crate."], "explanation": "Near miss (partial): \"the altarpiece must be crated to the lender''s specification\" (true, one link short). No conclusion stated. Trait 2.", "category": "Level 5: No clean indicator, unstated, qualified, or somebody else''s conclusion"}, {"order": 53, "prompt": "Good archival practice is ultimately a matter of judgment rather than rules. The retention schedule the state provides cannot anticipate the records this office generates. Half our series have no matching category, and the categories that do match were written for paper. So the schedule should be treated as a starting point, not an authority.", "credited_answers": ["The retention schedule should be treated as a starting point, not an authority."], "explanation": "Near miss (partial): \"the state schedule does not fit this office''s records\" (support). Wrong turn: the opening sentence, which is broad, confident, and supported by nothing. Trait 1. Note: his exact Trait 1 shape. Support beats sound.", "category": "Level 5: No clean indicator, unstated, qualified, or somebody else''s conclusion"}, {"order": 54, "prompt": "A total ban on rooftop beekeeping is too strong a response. Two hives on one building did swarm into a schoolyard. That building had eight hives on a roof rated for two. Nothing in the incident tells us anything about a properly limited hive count.", "credited_answers": ["A total ban is too strong a response."], "explanation": "Near miss (partial): \"the ban should be narrower.\" Wrong turn: \"rooftop beekeeping is safe\" (the overshoot the argument specifically does not license); also the swarm incident. No indicator; conclusion first. Trait 4. Note: the reasons refute an absolute ban and nothing more. This is the scope trap in its cleanest form.", "category": "Level 5: No clean indicator, unstated, qualified, or somebody else''s conclusion"}, {"order": 55, "prompt": "The department will lose the fellowship line whether or not it files an appeal. The appeal window closed in August, the provost''s memo calls the reallocation final, and the two departments that appealed last year received the letter we received. It would be better if the university funded these lines properly, but that is not what will happen here.", "credited_answers": ["The department will lose the fellowship line regardless of an appeal."], "explanation": "Near miss (partial): \"an appeal would fail.\" Wrong turn: \"the university should fund these lines properly\" (the author agrees with it and is not arguing it). No indicator; prediction in the first seat. Trait 5. Note: do not turn a prediction into a policy. If the argument predicts, the conclusion predicts.", "category": "Level 5: No clean indicator, unstated, qualified, or somebody else''s conclusion"}, {"order": 56, "prompt": "The dispute assumes a work is either an original or a copy. The workshop that produced these panels used a master''s drawing, the master''s pigments, and the master''s hand on the faces alone. Calling the panels copies erases what the master did. Calling them originals erases the workshop. The category this argument needs does not exist in the catalogue.", "credited_answers": ["The category the argument needs does not exist in the catalogue."], "explanation": "Near miss (partial): \"the panels are neither originals nor copies\" (an acceptable paraphrase, and worth crediting; a student who lands here has the idea). Wrong turn: \"the master painted the faces\" (concrete, memorable, a premise). No indicator; abstract conclusion in the final seat. Trait 6. Note: the correct answer is the abstract one sitting next to a vivid concrete distractor.", "category": "Level 5: No clean indicator, unstated, qualified, or somebody else''s conclusion"}, {"order": 57, "prompt": "Some members propose requiring a sponsor for every new applicant. Such a requirement would not do what they expect. The applicants the society has failed to attract do not know anyone who could sponsor them, and that is the substance of the problem the rule is meant to solve.", "credited_answers": ["(substituted): Requiring a sponsor for every applicant would not solve the society''s problem attracting applicants."], "explanation": "Near miss (partial): \"such a requirement would not do what they expect\" left referential. Wrong turn: the members'' proposal. Attribution plus referential rejection, no pivot word. Trait 3 plus substitution.", "category": "Level 5: No clean indicator, unstated, qualified, or somebody else''s conclusion"}, {"order": 58, "prompt": "The survey went to every household on the water system. Only nine percent responded, and respondents skewed heavily toward the two neighborhoods that already had complaints on file. The results cannot support a system-wide conclusion. The utility has nonetheless printed them in the annual report under the heading Customer Satisfaction.", "credited_answers": ["The results cannot support a system-wide conclusion."], "explanation": "Near miss (partial): \"the utility should not have printed the results\" (a reasonable extension the author does not state). Wrong turn: the final sentence (Last Claim Trap; it is a further fact). No indicator; conclusion sandwiched third of four. Trait 1 and the Last Claim Trap.", "category": "Level 5: No clean indicator, unstated, qualified, or somebody else''s conclusion"}, {"order": 59, "prompt": "The consultant''s report concludes that the branch should close because its transaction volume is the lowest in the region. Transaction volume is the wrong measure here. The branch handles the region''s only safe-deposit vault and most of its notarizations, and the report counts neither.", "credited_answers": ["Transaction volume is the wrong measure for this decision."], "explanation": "Near miss (partial): \"the branch should not close\" (the author implies it and argues something narrower). Wrong turn: \"the branch should close\" (the consultant''s conclusion, not the author''s). Two conclusions in one argument, one of them quoted. Trait 5. Note: separate the author''s conclusion from a conclusion the author is reporting.", "category": "Level 5: No clean indicator, unstated, qualified, or somebody else''s conclusion"}, {"order": 60, "prompt": "Even if the new filtration removes every trace of the compound, the district should not treat the well as a long-term source. The aquifer beneath it is recharged by the same fields where the compound originated, and filtration addresses what is already in the water rather than what keeps arriving.", "credited_answers": ["The district should not treat the well as a long-term source, even if filtration works completely."], "explanation": "Near miss (partial): \"filtration will not remove the compound\" (contradicts the concession the author granted); \"the district should not use the well\" (drops the long-term qualifier). No indicator; conclusion in the first seat behind an \"even if.\" Trait 4.", "category": "Level 5: No clean indicator, unstated, qualified, or somebody else''s conclusion"}, {"order": 61, "prompt": "The board''s timeline for the renovation is evidently optimistic. Permits alone took fourteen months on the last project of this size, and the drawings for this one are not finished.", "credited_answers": ["The board''s renovation timeline is optimistic."], "explanation": "Near miss (partial): \"the renovation will be late\" (a prediction the author does not quite make). Wrong turn: the fourteen-month figure. \"Evidently\" opinion indicator, no structural marker. Trait 4. Note: when nothing else marks the claim, an opinion indicator is the best clue available.", "category": "Level 5: No clean indicator, unstated, qualified, or somebody else''s conclusion"}, {"order": 62, "prompt": "The tool library will be out of the tile saw for the rest of the season. Requests are arriving at four times last spring''s rate, the member who donated it has stopped lending, and no one has offered a substitute.", "credited_answers": ["The tool library will be out of the tile saw for the rest of the season."], "explanation": "Near miss (partial): \"the tool library needs another tile saw\" (a sensible recommendation the argument does not make). Wrong turn: the request rate. No indicator at all; prediction in the first seat, three reasons after. Trait 5. Note: the closing bare case. No marker anywhere, so the 2-Point Check and the \"Why should we believe that?\" test are the only tools left, which is the point of putting it last.", "category": "Level 5: No clean indicator, unstated, qualified, or somebody else''s conclusion"}]'::jsonb
  ),
  (
    'conditional-rephrase',
    'Conditional Rephrase',
    'Put the statement into if-then, then turn it around',
    '{"coach": {"drill": "a conditional-translation drill: the student rewrites a statement as If [sufficient], then [necessary] and gives its contrapositive", "rubric": ["Either direction is credited. The if-then form and its contrapositive are the same statement, so a student who supplies only one of them has still translated correctly.", "The core judgment is which condition is sufficient and which is necessary. Words like if, when, whenever, every, all and ''the only'' mark the sufficient side. Words like only if, only when, unless, without, except, requires, presupposes, depends on, necessitates and must mark the necessary side.", "Compound conditions (''both X and Y'') and internal contrasts (''X rather than Y'') must be carried into the answer whole, not simplified away.", "Wording is free. Judge the logical structure, not the phrasing."], "partial_rule": "Mark ''partial'' when the student produces a well-formed conditional but reverses sufficiency and necessity, drops a negation, or trims a compound or contrasting condition down to one part. Mark ''incorrect'' when the response is not a conditional at all, or states a relationship the statement does not support."}, "tagline": "Find the trigger word, and it tells you which side is which.", "task": "Rephrase the statement as If [sufficient], then [necessary]. Then give me the contrapositive.", "rules": ["Some words introduce the sufficient condition and some introduce the necessary one. That is the whole game.", "If, when, whenever, every, all, the only: these mark the sufficient side, the trigger.", "Only if, only when, unless, without, requires, depends on, must: these mark the necessary side, what is required.", "A necessary condition is required but never a guarantee. It can be met and the thing still not happen.", "Contrapositive: negate both sides and swap them. Keep compound and contrasting conditions whole; do not simplify them away."], "worked_example": {"statement": "You can''t master the LSAT without mastering conditional reasoning.", "credited_answers": ["If you master the LSAT, then you master conditional reasoning.", "If you don''t master conditional reasoning, you won''t master the LSAT."], "explanation": "Without marks the necessary condition, so mastering conditional reasoning goes on the then side. Both forms above are credited: the second is just the contrapositive of the first."}}'::jsonb,
    'free-text',
    '[{"order": 1, "prompt": "Whenever the greenhouse fans run overnight, the orchids bloom by morning.", "credited_answers": ["If the fans run overnight, then the orchids bloom by morning.", "If the orchids did not bloom by morning, then the fans did not run overnight."], "explanation": "\"Whenever\" (sufficient). \"Whenever,\" like \"every\" and \"all,\" marks the sufficient side.", "category": "Level 1: Plain indicators, single condition"}, {"order": 2, "prompt": "Every manuscript accepted by the quarterly is read by two editors.", "credited_answers": ["If a manuscript is accepted by the quarterly, then it is read by two editors.", "If a manuscript was not read by two editors, then it was not accepted."], "explanation": "\"Every\" (sufficient). The noun phrase \"every…accepted\" goes whole into the if-clause.", "category": "Level 1: Plain indicators, single condition"}, {"order": 3, "prompt": "The drawbridge is raised only if a tall ship signals the operator.", "credited_answers": ["If the drawbridge is raised, then a tall ship signaled the operator.", "If no tall ship signaled, then the drawbridge is not raised."], "explanation": "\"Only if\" (necessary). The classic; signaling does not guarantee raising.", "category": "Level 1: Plain indicators, single condition"}, {"order": 4, "prompt": "When the kiln reaches firing temperature, the glaze sets within the hour.", "credited_answers": ["If the kiln reaches firing temperature, then the glaze sets within the hour.", "If the glaze did not set within the hour, the kiln did not reach temperature."], "explanation": "\"When\" (sufficient). \"When\" reads like time but works like \"if.\"", "category": "Level 1: Plain indicators, single condition"}, {"order": 5, "prompt": "All entries that win the pastry competition use seasonal fruit.", "credited_answers": ["If an entry wins, then it uses seasonal fruit.", "If an entry does not use seasonal fruit, it does not win."], "explanation": "\"All\" (sufficient). Reversal bait: using seasonal fruit guarantees nothing.", "category": "Level 1: Plain indicators, single condition"}, {"order": 6, "prompt": "The vault opens only when two floor managers are present.", "credited_answers": ["If the vault opens, then two floor managers are present.", "If two managers are not present, the vault does not open."], "explanation": "\"Only when\" (necessary). Twin of \"only if.\"", "category": "Level 1: Plain indicators, single condition"}, {"order": 7, "prompt": "None of the trails above the ridge line are open in March.", "credited_answers": ["If a trail is above the ridge line, then it is not open in March.", "If a trail is open in March, it is not above the ridge line."], "explanation": "\"None\" (sufficient subject, negated necessary). First negation-threading item.", "category": "Level 1: Plain indicators, single condition"}, {"order": 8, "prompt": "The choir performs outdoors if the evening stays dry.", "credited_answers": ["If the evening stays dry, then the choir performs outdoors.", "If the choir does not perform outdoors, the evening did not stay dry."], "explanation": "Mid-sentence \"if\" (sufficient). Outcome stated first; the if-clause still marks the trigger.", "category": "Level 1: Plain indicators, single condition"}, {"order": 9, "prompt": "Unless the generator is refueled by dusk, the beacon goes dark.", "credited_answers": ["If the generator is not refueled by dusk, then the beacon goes dark.", "If the beacon did not go dark, the generator was refueled by dusk."], "explanation": "\"Unless\" (= if not). The workhorse translation: unless = if not.", "category": "Level 2: The negative-required family"}, {"order": 10, "prompt": "Without a permit, no vendor may sell at the night market.", "credited_answers": ["If a vendor sells at the night market, then the vendor has a permit.", "If a vendor has no permit, the vendor may not sell."], "explanation": "\"Without\" (necessary). Double negative resolves cleanly.", "category": "Level 2: The negative-required family"}, {"order": 11, "prompt": "A climber cannot attempt the summit without registering at the base station.", "credited_answers": ["If a climber attempts the summit, then the climber registered at the base station.", "If a climber did not register, the climber cannot attempt the summit."], "explanation": "\"Cannot…without\" (necessary). The reference-statement form.", "category": "Level 2: The negative-required family"}, {"order": 12, "prompt": "Except during festival week, the archive reading room stays locked.", "credited_answers": ["If it is not festival week, then the reading room is locked.", "If the reading room is unlocked, it is festival week."], "explanation": "\"Except\" (exception = the only escape). Exception-first order; the exception is not a guarantee of unlocking.", "category": "Level 2: The negative-required family"}, {"order": 13, "prompt": "The orchestra tours in the spring unless the hall renovation runs late.", "credited_answers": ["If the renovation does not run late, then the orchestra tours in the spring.", "If the orchestra does not tour, the renovation ran late."], "explanation": "\"Unless\" trailing. Same rule as item 9 with the clauses reversed on the page.", "category": "Level 2: The negative-required family"}, {"order": 14, "prompt": "No thesis passes the review board without an outside reader''s signature.", "credited_answers": ["If a thesis passes, then an outside reader signed.", "No signature, no pass."], "explanation": "\"No…without\" (necessary). Signature is required, not sufficient; the board can still reject.", "category": "Level 2: The negative-required family"}, {"order": 15, "prompt": "The museum does not deaccession a painting unless the donor''s estate consents.", "credited_answers": ["If the museum deaccessions a painting, then the estate consented.", "If the estate did not consent, the museum does not deaccession."], "explanation": "\"Not…unless\" (necessary). Negative main clause + unless: the pair students scramble most.", "category": "Level 2: The negative-required family"}, {"order": 16, "prompt": "The relay team advances only with a clean baton exchange.", "credited_answers": ["If the team advances, then the exchange was clean.", "If the exchange was not clean, the team does not advance."], "explanation": "\"Only with\" (necessary). \"Only\" attaching to a phrase, not a clause.", "category": "Level 2: The negative-required family"}, {"order": 17, "prompt": "Except where the levee has been reinforced, the river road closes during spring melt.", "credited_answers": ["If the levee has not been reinforced, then the road closes during spring melt.", "If the road stays open, the levee was reinforced."], "explanation": "\"Except where\" (his seed''s indicator). Exception-first; reinforcement permits, never guarantees, an open road.", "category": "Level 2: The negative-required family"}, {"order": 18, "prompt": "Absent a unanimous vote, the bylaws stay unchanged.", "credited_answers": ["If the vote is not unanimous, then the bylaws stay unchanged.", "If the bylaws changed, the vote was unanimous."], "explanation": "\"Absent\" (= without). New synonym for the family; one word carrying the whole structure.", "category": "Level 2: The negative-required family"}, {"order": 19, "prompt": "The only candles sold at the apiary are poured from the hive''s own wax.", "credited_answers": ["If a candle is sold at the apiary, then it is poured from the hive''s wax.", "Not hive wax, not sold there."], "explanation": "\"The only\" (SUFFICIENT: the described thing goes in the if-clause). The look-alike that flips sides; drill adjacent to item 20.", "category": "Level 3: \"The only\" vs \"only,\" and the verb indicators"}, {"order": 20, "prompt": "Only cellists who audition in person join the chamber ensemble.", "credited_answers": ["If a musician joins the ensemble, then that musician is a cellist who auditioned in person.", "No in-person audition, no seat."], "explanation": "\"Only\" (necessary). The discrimination pair with 19: one word of difference, opposite structure.", "category": "Level 3: \"The only\" vs \"only,\" and the verb indicators"}, {"order": 21, "prompt": "Certification as a master falconer requires five seasons of supervised apprenticeship.", "credited_answers": ["If someone is certified, then they completed five seasons.", "No five seasons, no certification."], "explanation": "\"Requires\" (necessary verb). First of the verb indicators: no \"if\" anywhere.", "category": "Level 3: \"The only\" vs \"only,\" and the verb indicators"}, {"order": 22, "prompt": "Dating the shipwreck to the spice trade presupposes that the hull timber was felled after the monsoon routes opened.", "credited_answers": ["If the wreck is dated to the spice trade, then the timber was felled after the routes opened.", "Felled earlier, not so dated."], "explanation": "\"Presupposes\" (necessary verb). His palimpsest pattern in new clothes.", "category": "Level 3: \"The only\" vs \"only,\" and the verb indicators"}, {"order": 23, "prompt": "Whether the observatory renews the comet survey depends on funding from the maritime trust.", "credited_answers": ["If the survey is renewed, then the trust funded it.", "No funding, no renewal."], "explanation": "\"Depends on\" (necessary verb). Funding permits renewal; it does not guarantee it.", "category": "Level 3: \"The only\" vs \"only,\" and the verb indicators"}, {"order": 24, "prompt": "Entering the archive''s cold vault necessitates logging the visit with the conservator on duty.", "credited_answers": ["If someone enters the vault, then the visit was logged.", "Not logged, no entry."], "explanation": "\"Necessitates\" (necessary verb). Mid-sentence sophistication, per his tremor seed.", "category": "Level 3: \"The only\" vs \"only,\" and the verb indicators"}, {"order": 25, "prompt": "A perfect score on the final audition guarantees a seat in the touring company.", "credited_answers": ["If the audition score is perfect, then a seat is guaranteed.", "No seat, the score was not perfect."], "explanation": "\"Guarantees\" (SUFFICIENT verb). The counterweight: some verbs mark the sufficient side. Requires vs guarantees is the level''s core discrimination.", "category": "Level 3: \"The only\" vs \"only,\" and the verb indicators"}, {"order": 26, "prompt": "Sealing the ferment under an airlock ensures the batch survives the summer heat.", "credited_answers": ["If the ferment is sealed under an airlock, then the batch survives.", "Batch spoiled, it was not sealed."], "explanation": "\"Ensures\" (sufficient verb). Sibling of 25.", "category": "Level 3: \"The only\" vs \"only,\" and the verb indicators"}, {"order": 27, "prompt": "Restoring the fresco''s cobalt border demands pigment ground from the original quarry.", "credited_answers": ["If the border is restored, then quarry-ground pigment was used.", "No quarry pigment, no restoration."], "explanation": "\"Demands\" (necessary verb). Verb lexicon depth.", "category": "Level 3: \"The only\" vs \"only,\" and the verb indicators"}, {"order": 28, "prompt": "A stable magnetic bearing is essential to calibrating the drone''s compass.", "credited_answers": ["If the compass is calibrated, then the bearing was stable.", "Unstable bearing, no calibration."], "explanation": "\"Essential to\" (necessary). Adjective form of the same move.", "category": "Level 3: \"The only\" vs \"only,\" and the verb indicators"}, {"order": 29, "prompt": "Except where the surveyor has verified both the boundary markers and the floodplain easement, the records office will not transfer the deed.", "credited_answers": ["If the deed is transferred, then both the markers and the easement were verified.", "If either was unverified, no transfer."], "explanation": "\"Except where\" + compound. Both conjuncts must survive; \"either unverified\" is the contrapositive''s hinge.", "category": "Level 4: Full load: order, compounds, contrasts, jargon"}, {"order": 30, "prompt": "Classifying the manuscript hand as professional necessitates matching its letterforms to guild exemplars rather than to household copybooks.", "credited_answers": ["If the hand is classified as professional, then its letterforms match guild exemplars rather than household copybooks.", "If they do not match guild exemplars rather than copybooks, not classified professional."], "explanation": "\"Necessitates\" + internal contrast. The \"rather than\" clause is part of the condition; trimming it is a partial.", "category": "Level 4: Full load: order, compounds, contrasts, jargon"}, {"order": 31, "prompt": "The only expeditions cleared for the ice shelf carry redundant beacons and a certified glacier medic.", "credited_answers": ["If an expedition is cleared, then it carries both.", "Missing either, not cleared."], "explanation": "\"The only\" + compound. Level 3''s flip under load.", "category": "Level 4: Full load: order, compounds, contrasts, jargon"}, {"order": 32, "prompt": "Unless the tasting panel finds no trace of cork taint, the vintage is not released under the estate label.", "credited_answers": ["If the vintage is released under the estate label, then the panel found no trace of taint.", "If any taint was found, no estate release."], "explanation": "\"Unless\" + embedded negative. Three negatives thread into one clean pair.", "category": "Level 4: Full load: order, compounds, contrasts, jargon"}, {"order": 33, "prompt": "Attributing the seismic swarm to hydrothermal circulation presupposes that the tremor spectra lack the impulsive onsets characteristic of tectonic slip.", "credited_answers": ["If the swarm is attributed to hydrothermal circulation, then the spectra lack impulsive onsets.", "Impulsive onsets present, no such attribution."], "explanation": "\"Presupposes\" under jargon. The structure is three words long; everything else is noise to see through.", "category": "Level 4: Full load: order, compounds, contrasts, jargon"}, {"order": 34, "prompt": "Only when the reef survey records juvenile parrotfish at three consecutive stations does the marine reserve loosen its no-anchor rule.", "credited_answers": ["If the reserve loosens the rule, then the survey recorded juveniles at three consecutive stations.", "No three-station record, no loosening."], "explanation": "\"Only when\" + inverted syntax. The inversion (\"does the reserve…\") hides which clause is the outcome.", "category": "Level 4: Full load: order, compounds, contrasts, jargon"}, {"order": 35, "prompt": "No restoration receives the guild''s seal without both a reversible adhesive and a documented provenance chain.", "credited_answers": ["If a restoration receives the seal, then it used a reversible adhesive and has a provenance chain.", "Lacking either, no seal."], "explanation": "\"No…without\" + compound. Family capstone.", "category": "Level 4: Full load: order, compounds, contrasts, jargon"}, {"order": 36, "prompt": "A confirmed match in the pollen record guarantees a spring dating for the flood layer, but only a sealed stratum makes the match itself trustworthy.", "credited_answers": ["If the pollen match is confirmed (and trustworthy), then the flood layer dates to spring; and if the match is trustworthy, then the stratum was sealed.", "-chain: unsealed stratum, untrustworthy match; no trustworthy match, no confirmed spring dating."], "explanation": "\"Guarantees\" + \"only.\" Two conditionals in one sentence; the Chain Yard''s doorstep, and the bank''s hardest item.", "category": "Level 4: Full load: order, compounds, contrasts, jargon"}, {"order": 37, "prompt": "The curing shed stays sealed until the humidity gauge reads forty percent.", "credited_answers": ["If the gauge has not read forty percent, then the shed stays sealed.", "If the shed is unsealed, the gauge read forty percent."], "explanation": "\"Until\" (the unlock condition is necessary for the change). The state persists as long as the condition is unmet.", "category": "Until / not until"}, {"order": 38, "prompt": "Not until the auditor countersigns the ledger does the treasury release quarterly funds.", "credited_answers": ["If funds are released, then the auditor countersigned.", "No countersignature, no release."], "explanation": "\"Not until,\" sentence-initial with inverted syntax. Twin of \"only when\" in disguise.", "category": "Until / not until"}, {"order": 39, "prompt": "Snow leopards never abandon a den before the cubs can climb.", "credited_answers": ["If the cubs cannot yet climb, then the den is not abandoned.", "If a den is abandoned, the cubs can climb."], "explanation": "\"Never\" (universal negative). \"Never\" builds a conditional with a negated result.", "category": "Never"}, {"order": 40, "prompt": "The registrar never certifies a transcript that lacks the dean''s seal.", "credited_answers": ["If a transcript is certified, then it carries the dean''s seal.", "No seal, no certification."], "explanation": "\"Never,\" mid-sentence. The negative universal quietly marks the subject as sufficient.", "category": "Never"}, {"order": 41, "prompt": "A kite cannot hold altitude in dead air.", "credited_answers": ["If the air is dead, then a kite does not hold altitude.", "If a kite holds altitude, the air is not dead."], "explanation": "\"Cannot\" (impossibility). Impossibility statements are conditionals wearing a flat disguise.", "category": "Cannot (standalone)"}, {"order": 42, "prompt": "Sealed bids cannot be amended after the auction gavel falls.", "credited_answers": ["If the gavel has fallen, then bids cannot be amended.", "If a bid was amended, the gavel had not fallen."], "explanation": "\"Cannot,\" sentence-final condition. The time clause is the sufficient side.", "category": "Cannot (standalone)"}, {"order": 43, "prompt": "The festival committee will not book both the brass band and the string quartet.", "credited_answers": ["If the brass band is booked, then the quartet is not (and the reverse).", "same rule from the other side."], "explanation": "\"Not both\" (A → not B). Not-both allows neither; it only forbids the pair.", "category": "Not both"}, {"order": 44, "prompt": "A juror may review the exhibit log or the testimony transcripts overnight, but not both.", "credited_answers": ["If a juror reviews the log, then not the transcripts (and the reverse)."], "explanation": "\"But not both,\" sentence-final. The or-with-a-cap construction; \"or\" here still permits either alone.", "category": "Not both"}, {"order": 45, "prompt": "The saplings recover if only the deer fencing goes up before bud break.", "credited_answers": ["If the fencing goes up before bud break, then the saplings recover.", "If the saplings did not recover, the fencing did not go up in time."], "explanation": "\"If only\" (SUFFICIENT). The discrimination pair with \"only if\": in \"only if,\" the only governs the if (necessary); in \"if only,\" the if still marks the sufficient side and \"only\" just says the requirement is small. One word order, opposite structure.", "category": "If only (the look-alike of \"only if\")"}, {"order": 46, "prompt": "File the appeal by Thursday, or else the ruling becomes final.", "credited_answers": ["If the appeal is not filed by Thursday, then the ruling becomes final.", "If the ruling did not become final, the appeal was filed in time."], "explanation": "\"Or else\" (= if not). Commands hide conditionals.", "category": "Or else / otherwise"}, {"order": 47, "prompt": "The reef pumps must cycle nightly; otherwise the tank crashes.", "credited_answers": ["If the pumps do not cycle nightly, then the tank crashes.", "Tank fine, pumps cycled."], "explanation": "\"Otherwise\" (= if not). Sibling of \"or else\" across a semicolon.", "category": "Or else / otherwise"}, {"order": 48, "prompt": "Visiting scholars must clear the manuscript room''s ultraviolet screening.", "credited_answers": ["If someone works in the manuscript room as a visiting scholar, then they cleared the screening.", "Not cleared, not admitted."], "explanation": "\"Must\" (necessary). Requirement language: must marks what is required, never what suffices.", "category": "Must / in order to / the only way"}, {"order": 49, "prompt": "In order to bottle under the heritage label, a cidery has to press fruit from registered orchards.", "credited_answers": ["If a cidery bottles under the label, then it pressed registered fruit.", "No registered fruit, no label."], "explanation": "\"In order to\" (the goal side is sufficient; the stated requirement is necessary). Purpose framing.", "category": "Must / in order to / the only way"}, {"order": 50, "prompt": "The only way to reach the fire lookout before noon is the switchback trail.", "credited_answers": ["If you reach the lookout before noon, then you took the switchback trail.", "Not the switchback, not before noon."], "explanation": "\"The only way\" (necessary). Cousin of \"the only,\" pointing the other direction: here the described thing is the requirement.", "category": "Must / in order to / the only way"}, {"order": 51, "prompt": "The loan converts to a grant provided that the clinic stays open five years.", "credited_answers": ["If the clinic stays open five years, then the loan converts.", "No conversion, it did not stay open."], "explanation": "\"Provided that\" (sufficient).", "category": "Provided that / as long as / on the condition that"}, {"order": 52, "prompt": "As long as the yeast stays refrigerated, the starter keeps its rise.", "credited_answers": ["If the yeast stays refrigerated, then the starter keeps its rise.", "Lost its rise, it was not kept cold."], "explanation": "\"As long as\" (sufficient). Duration framing of \"if.\"", "category": "Provided that / as long as / on the condition that"}, {"order": 53, "prompt": "The painting travels on the condition that the borrower installs seismic mounts.", "credited_answers": ["If the painting travels, then the mounts are installed.", "No mounts, no travel."], "explanation": "\"On the condition that\" (NECESSARY). The trio''s discrimination: provided-that and as-long-as mark the sufficient side; on-the-condition-that states a requirement.", "category": "Provided that / as long as / on the condition that"}, {"order": 54, "prompt": "No one boards the research vessel unless the harbor physician signs their medical card.", "credited_answers": ["If someone boards, then the physician signed their card.", "No signature, no boarding."], "explanation": "\"No one…unless.\" Two negatives and an unless resolving into one clean rule.", "category": "No one … unless / biconditional"}, {"order": 55, "prompt": "The observatory grants dark-sky certification if and only if every fixture in the district is fully shielded.", "credited_answers": ["Both directions: If certified, then every fixture is shielded; and if every fixture is shielded, then certified.", "either direction negated."], "explanation": "\"If and only if\" (biconditional). The one construction where both sides are both sufficient and necessary; flag it as rare and special.", "category": "No one … unless / biconditional"}, {"order": 56, "prompt": "The senate ratifies the water compact only if every border county holds a public hearing.", "credited_answers": ["Ratified → hearings held."], "explanation": "The textbook seat. Seat: final.", "category": "\"Only if\" in three seats"}, {"order": 57, "prompt": "Only if every border county holds a public hearing does the senate ratify the water compact.", "credited_answers": ["Same translation exactly."], "explanation": "Fronting changes emphasis, never structure; the inversion (\"does the senate…\") is the disguise. Seat: initial, inverted.", "category": "\"Only if\" in three seats"}, {"order": 58, "prompt": "Ratification of the compact, which the senate grants only if every border county has held a hearing, remains stalled this term.", "credited_answers": ["Same rule, buried in a relative clause inside a sentence about something else."], "explanation": "Extraction under load. Seat: mid, embedded.", "category": "\"Only if\" in three seats"}, {"order": 59, "prompt": "Unless the dye bath holds at a simmer, the wool takes the color unevenly.", "credited_answers": ["If the bath does not hold at a simmer, the wool takes color unevenly."], "explanation": "Seat: initial.", "category": "\"Unless\" in three seats"}, {"order": 60, "prompt": "The wool takes the color unevenly unless the dye bath holds at a simmer.", "credited_answers": ["Identical translation; the clause order flipped on the page."], "explanation": "Seat: final.", "category": "\"Unless\" in three seats"}, {"order": 61, "prompt": "Every batch this season, unless the dye bath held at a simmer throughout, has come out mottled.", "credited_answers": ["Same rule inside an interrupting clause."], "explanation": "The eye must reassemble the split main clause. Seat: mid, embedded.", "category": "\"Unless\" in three seats"}, {"order": 62, "prompt": "Without the harbormaster''s stamp, no manifest clears customs.", "credited_answers": ["If a manifest clears, then it carries the stamp."], "explanation": "One rule, two seats; drilled as a single item pair. Seat: initial. Same rule in final position: \"No manifest clears customs without the harbormaster''s stamp.\"", "category": "\"Without\" in two seats"}]'::jsonb
  ),
  (
    'rebuttal-rephrase',
    'Rebuttal Rephrase',
    'Say what the author actually believes, at the author''s exact strength',
    '{"coach": {"drill": "a rebuttal-rephrasing drill: the argument''s conclusion is a referential rejection of somebody else''s claim, and the student must restate it in content terms", "rubric": ["The credited answer is the MINIMAL negation of the attributed claim, stated in content terms, preserving the author''s exact level of certainty.", "Minimal means smallest: the negation of ''can never'' is ''can sometimes'', never ''can always''. The negation of ''no'' is ''at least one'', never ''many''. The negation of ''must'' is ''not necessarily'', never ''definitely not''.", "Every qualifier in the original claim must survive into the answer. If the claim said ''exclusively'' or ''in every filing'' or named a comparison, an answer that drops it has changed the claim.", "Where the author concedes one claim and rejects another, a correct answer carries both moves. Contradicting something the author granted is not correct."], "partial_rule": "Mark ''partial'' when the student has the right claim but overshoots to the polar opposite, or drops a scope qualifier, or leaves the referential phrase unresolved (''these researchers are mistaken'' with no content substituted). Mark ''incorrect'' when they answer with the evidence rather than the conclusion, restate the attributed claim as if the author endorsed it, or address a different claim entirely."}, "tagline": "They''re wrong is the conclusion. It is not yet an answer.", "task": "Two steps. First find the conclusion of the argument. Then rephrase it, replacing the referential language with the claim it actually points at.", "rules": ["Every one of these arguments has the same anatomy: somebody else''s claim, then the author rejecting it. The rejection is the conclusion, and on its own it says nothing.", "The credited answer is the smallest negation of the attributed claim, stated in content terms.", "Preserve the author''s level of certainty. The negation of can never is can sometimes, not can always.", "Keep every qualifier. If the claim said exclusively, your answer still says exclusively.", "Do not answer with the evidence. The evidence supports the conclusion; it is not the conclusion."], "worked_example": {"statement": "People think gum is food, but they''re wrong.", "credited_answers": ["Gum is not food."], "explanation": "The explicit conclusion is they''re wrong. That is the sentence you locate. What we want to hear is what it means: gum is not food. Every item in this activity is that move on harder material."}}'::jsonb,
    'free-text',
    '[{"order": 1, "prompt": "Although some luthiers maintain that a violin top cannot be regraduated without dulling its tone, this is not so.", "credited_answers": ["A violin top can be regraduated without dulling its tone."], "explanation": "Overshoot to refuse: \"regraduation improves tone.\" Attribution \"some luthiers maintain\" \"cannot\" \"this is not so.\" Note: the flip is *can*, and it stops there. The author has not said regraduation is good.", "category": "Level 1: Bare flip"}, {"order": 2, "prompt": "That is mistaken. Curators have argued that a panel painting cannot be moved safely once its cradle is removed.", "credited_answers": ["A panel painting can be moved safely after its cradle is removed."], "explanation": "Rejection before the attribution. Note: order is reversed on the page and the task does not change. Find the attributed claim first, wherever it sits.", "category": "Level 1: Bare flip"}, {"order": 3, "prompt": "A number of coaches hold that it is impossible to correct a swimmer''s catch after adolescence. They are wrong.", "credited_answers": ["It is possible to correct a swimmer''s catch after adolescence."], "explanation": "Overshoot: \"the catch is easiest to correct after adolescence.\" \"impossible\" \"they are wrong.\"", "category": "Level 1: Bare flip"}, {"order": 4, "prompt": "The standard account says that no medieval scriptorium employed women as copyists. The account does not hold.", "credited_answers": ["At least one medieval scriptorium employed women as copyists."], "explanation": "Overshoot: \"many scriptoria employed women.\" Note: the negation of *no* is *at least one*. Not \"many,\" not \"most,\" not \"commonly.\" This is the single most common overshoot in the level.", "category": "Level 1: Bare flip"}, {"order": 5, "prompt": "Some agronomists maintain that saline soils cannot support a cereal crop, a position that cannot be sustained.", "credited_answers": ["Saline soils can support a cereal crop."], "explanation": "Rejection embedded in the same sentence as an apposition. Note: no pivot word at all. The rejection arrives as a relative clause.", "category": "Level 1: Bare flip"}, {"order": 6, "prompt": "It is widely assumed that a building of this period could not have carried a glazed clerestory. The assumption is false.", "credited_answers": ["A building of this period could have carried a glazed clerestory."], "explanation": "Overshoot: \"buildings of this period did carry glazed clerestories.\" Note: *could have* is a possibility claim. Negating it yields possibility, not fact.", "category": "Level 1: Bare flip"}, {"order": 7, "prompt": "Several reviewers insist that a chamber work cannot be scored for these four instruments without imbalance. Not so.", "credited_answers": ["A chamber work can be scored for these four instruments without imbalance."], "explanation": "Scope note: \"without imbalance\" must survive. \"A chamber work can be scored for these four instruments\" is a scope drop, and a much weaker claim.", "category": "Level 1: Bare flip"}, {"order": 8, "prompt": "Some archivists contend that a nitrate negative cannot be duplicated once decay has begun. This claim is incorrect.", "credited_answers": ["A nitrate negative can be duplicated after decay has begun."], "explanation": "Scope note: \"once decay has begun\" is the whole point of the dispute. Dropping it concedes nothing and claims nothing.", "category": "Level 1: Bare flip"}, {"order": 9, "prompt": "The prevailing view holds that no untrained listener can distinguish the two dialects. That view fails.", "credited_answers": ["At least one untrained listener can distinguish the two dialects."], "explanation": "Overshoot: \"untrained listeners can distinguish the two dialects\" (reads as a general capacity). \"no\" plus \"can.\"", "category": "Level 1: Bare flip"}, {"order": 10, "prompt": "Engineers on the review panel argued that a timber floor of this span cannot carry the intended load. Their argument does not survive scrutiny.", "credited_answers": ["A timber floor of this span can carry the intended load."], "explanation": "Note: \"does not survive scrutiny\" is a rejection dressed as an assessment. It behaves exactly like \"this is not so.\"", "category": "Level 1: Bare flip"}, {"order": 11, "prompt": "Some conservators claim that infrared reflectography can never recover an underdrawing beneath a lead-white ground. Reflectography at 2.2 microns recovered the full underdrawing on the Ghent panel, whose ground is lead white. These conservators are mistaken.", "credited_answers": ["Infrared reflectography can sometimes recover an underdrawing beneath a lead-white ground."], "explanation": "An even more precise answer folds in the evidence: it can do so at 2.2 microns. Overshoot: \"can always recover.\" Premise trap: \"reflectography recovered the underdrawing on the Ghent panel\" is the evidence, not the conclusion. \"never\" → \"sometimes.\"", "category": "Level 2: Quantifier negation with evidence present"}, {"order": 12, "prompt": "It is often said that every surviving copy of the broadside was printed from the same forme. Two copies show a turned letter in the fourth line that the others do not. The claim is wrong.", "credited_answers": ["Not every surviving copy was printed from the same forme."], "explanation": "An even more precise answer folds in the evidence: at least two were printed from a different setting. Overshoot: \"no two copies came from the same forme.\" Note: the negation of *every* is *not every*, which is compatible with almost all of them matching.", "category": "Level 2: Quantifier negation with evidence present"}, {"order": 13, "prompt": "A number of hydrologists maintain that a losing stream never recharges the aquifer beneath it. Tracer dye released above the reach appeared in two monitoring wells within a week. That position cannot stand.", "credited_answers": ["A losing stream can sometimes recharge the aquifer beneath it."], "explanation": "An even more precise answer folds in the evidence: it can do so within a week over this reach. Premise trap: the dye result. Overshoot: \"a losing stream always recharges the aquifer.\"", "category": "Level 2: Quantifier negation with evidence present"}, {"order": 14, "prompt": "The committee''s report states that all applicants rejected at the first stage lacked the required certification. Three of last year''s first-stage rejections held current certification. The report is in error.", "credited_answers": ["Not all applicants rejected at the first stage lacked the certification."], "explanation": "An even more precise answer folds in the evidence: at least three held it. Overshoot: \"the rejected applicants held the certification\" (reads as all of them). Note: *all* negates to *not all*, which the three cases establish exactly.", "category": "Level 2: Quantifier negation with evidence present"}, {"order": 15, "prompt": "Some ethnomusicologists argue that a work notated in this system can never be performed at its original tempo. The treatise gives a pendulum length for the opening movement. This inference is unwarranted.", "credited_answers": ["A work notated in this system can sometimes be performed at its original tempo."], "explanation": "An even more precise answer folds in the evidence: at least where a pendulum length survives, as it does for the opening movement. Premise trap: the pendulum length itself. \"never\" → \"sometimes.\"", "category": "Level 2: Quantifier negation with evidence present"}, {"order": 16, "prompt": "It is a common assumption that a kiln of this type always fires unevenly across the chamber. Pyrometric cones placed at four heights in the Aswan kiln fell within one cone of each other. The assumption is unsound.", "credited_answers": ["A kiln of this type does not always fire unevenly across the chamber."], "explanation": "An even more precise answer folds in the evidence: at least one fired within one cone across four heights. Overshoot: \"a kiln of this type fires evenly.\" \"always\" → \"not always.\"", "category": "Level 2: Quantifier negation with evidence present"}, {"order": 17, "prompt": "Several economists have written that a currency board never survives a terms-of-trade shock of this magnitude. Two boards in the region held through shocks larger than the one under discussion. They are wrong about this.", "credited_answers": ["A currency board can sometimes survive a terms-of-trade shock of this magnitude."], "explanation": "An even more precise answer folds in the evidence: at least two have survived larger ones. Premise trap: the two boards. Note: \"wrong about this\" is narrow. The author rejects one claim, not the economists generally.", "category": "Level 2: Quantifier negation with evidence present"}, {"order": 18, "prompt": "The catalogue asserts that none of the workshop''s signed pieces postdate the master''s death. One signed piece bears a hallmark introduced two years after. The catalogue is incorrect on this point.", "credited_answers": ["At least one signed piece postdates the master''s death."], "explanation": "An even more precise answer folds in the evidence: at least one bears a hallmark introduced two years after. Overshoot: \"the signed pieces postdate the master''s death.\" \"none\" → \"at least one.\"", "category": "Level 2: Quantifier negation with evidence present"}, {"order": 19, "prompt": "Some clinicians hold that a patient with this deficiency can never tolerate the standard dose. In the cohort described, four patients completed the full course without adverse events. That conclusion does not follow.", "credited_answers": ["A patient with this deficiency can sometimes tolerate the standard dose."], "explanation": "An even more precise answer folds in the evidence: at least four completed the full course without adverse events. Premise trap: the cohort result. Overshoot: \"patients with this deficiency tolerate the standard dose.\"", "category": "Level 2: Quantifier negation with evidence present"}, {"order": 20, "prompt": "It is frequently claimed that every dialect in the valley lost the final vowel by the tenth century. The northern recordings preserve it in unstressed position. The claim is false.", "credited_answers": ["Not every dialect in the valley lost the final vowel by the tenth century."], "explanation": "An even more precise answer folds in the evidence: the northern dialects preserve it in unstressed position. Scope note: \"in unstressed position\" is a real limit. An answer saying the northern dialects kept the final vowel outright overstates the evidence.", "category": "Level 2: Quantifier negation with evidence present"}, {"order": 21, "prompt": "Reviewers of the first edition wrote that the author never cites a source outside the two archives. The appendix quotes a letter held in a private collection. Those reviewers were mistaken.", "credited_answers": ["The author sometimes cites a source outside the two archives."], "explanation": "An even more precise answer folds in the evidence: at least once, a letter in a private collection. Overshoot: \"the author cites widely outside the two archives.\"", "category": "Level 2: Quantifier negation with evidence present"}, {"order": 22, "prompt": "A standard textbook claims that all reactions of this class require a metal catalyst. The Hoffman preparation runs to completion in its absence. This is not correct.", "credited_answers": ["Not all reactions of this class require a metal catalyst."], "explanation": "An even more precise answer folds in the evidence: the Hoffman preparation does not. Overshoot: \"reactions of this class do not require a metal catalyst.\" Note: watch the difference between *not all require* and *none require*. Only the first is earned.", "category": "Level 2: Quantifier negation with evidence present"}, {"order": 23, "prompt": "It is erroneous to infer that any kiln site yielding wasters must have been a production centre rather than a dump.", "credited_answers": ["A kiln site yielding wasters was not necessarily a production centre rather than a dump."], "explanation": "Scope note: \"rather than a dump\" is the contrast the claim was built on; an answer that says only \"was not necessarily a production centre\" has dropped half of it. Negate the necessity, not the fact. The author is not saying no such site was a production centre. Rejection wraps the claim.", "category": "Level 3: Nested modality and scope"}, {"order": 24, "prompt": "There is no warrant for the conclusion that every manuscript in this hand must have been copied in the same scriptorium.", "credited_answers": ["Manuscripts in this hand were not necessarily all copied in the same scriptorium."], "explanation": "Overshoot: \"manuscripts in this hand were copied in different scriptoria.\" Note: two strength words stacked, *every* and *must*. The minimal negation loosens the necessity and leaves the rest alone.", "category": "Level 3: Nested modality and scope"}, {"order": 25, "prompt": "The inference that any sediment core showing this ash layer must record the same eruption is unfounded.", "credited_answers": ["A sediment core showing this ash layer does not necessarily record that eruption."], "explanation": "Overshoot: \"cores showing this layer record different eruptions.\" Rejection trails the wrapped claim.", "category": "Level 3: Nested modality and scope"}, {"order": 26, "prompt": "One cannot conclude from the residue alone that these vessels must have been reserved exclusively for ritual use.", "credited_answers": ["These vessels were not necessarily reserved exclusively for ritual use."], "explanation": "Scope note: \"exclusively\" must survive. \"These vessels were not reserved for ritual use\" is a different and much stronger claim the author never makes. Note: \"from the residue alone\" also limits the rejection; the author objects to the inference from that one evidence type.", "category": "Level 3: Nested modality and scope"}, {"order": 27, "prompt": "It does not follow that a firm reporting under the older standard must have understated its liabilities in every filing.", "credited_answers": ["A firm reporting under the older standard did not necessarily understate its liabilities in every filing."], "explanation": "Scope note: \"in every filing\" survives. Dropping it produces \"did not understate its liabilities,\" which is far stronger than the author''s point. Two qualifiers to thread: *must* and *every*.", "category": "Level 3: Nested modality and scope"}, {"order": 28, "prompt": "The claim that any settlement abandoned in this period must have been abandoned because of the drought cannot be sustained.", "credited_answers": ["A settlement abandoned in this period was not necessarily abandoned because of the drought."], "explanation": "Overshoot: \"the drought did not cause these abandonments.\" Note: the author objects to the *necessity* of the causal claim, leaving the drought available as one cause among others.", "category": "Level 3: Nested modality and scope"}, {"order": 29, "prompt": "There is no basis for holding that a signature in this ink must postdate the workshop''s move to Antwerp.", "credited_answers": ["A signature in this ink does not necessarily postdate the move to Antwerp."], "explanation": "Overshoot: \"signatures in this ink predate the move.\"", "category": "Level 3: Nested modality and scope"}, {"order": 30, "prompt": "It is a mistake to suppose that a species found only in these two valleys must have originated in one of them.", "credited_answers": ["A species found only in these two valleys did not necessarily originate in either."], "explanation": "Scope note: \"found only in these two valleys\" is the setup and stays intact; the necessity is what falls. Note: \"one of them\" negates to \"either,\" which students routinely render as \"neither,\" an overshoot.", "category": "Level 3: Nested modality and scope"}, {"order": 31, "prompt": "That a tremor recorded at this depth must be volcanic rather than tectonic is an inference the data do not support.", "credited_answers": ["A tremor recorded at this depth is not necessarily volcanic rather than tectonic."], "explanation": "Scope note: the internal contrast \"rather than tectonic\" survives whole. Rejection is the sentence''s predicate, with the claim as its subject.", "category": "Level 3: Nested modality and scope"}, {"order": 32, "prompt": "We should not accept that any endorsement collected under the older rule must be treated as valid for the full term.", "credited_answers": ["An endorsement collected under the older rule need not be treated as valid for the full term."], "explanation": "Scope note: \"for the full term\" survives; without it the claim becomes \"need not be treated as valid,\" which is a different objection.", "category": "Level 3: Nested modality and scope"}, {"order": 33, "prompt": "The suggestion that every panel with this ground preparation must come from the same workshop does not withstand examination.", "credited_answers": ["Panels with this ground preparation do not all necessarily come from the same workshop."], "explanation": "Overshoot: \"these panels come from different workshops.\"", "category": "Level 3: Nested modality and scope"}, {"order": 34, "prompt": "It is erroneous to infer that a text surviving in a single witness must be less reliable than one surviving in many.", "credited_answers": ["A text surviving in a single witness is not necessarily less reliable than one surviving in many."], "explanation": "Scope note: the comparison is the claim. An answer saying \"a single-witness text is reliable\" both drops the comparison and overshoots the necessity.", "category": "Level 3: Nested modality and scope"}, {"order": 35, "prompt": "Some economists argue that the deposit scheme raised recycling rates and that it did so at no cost to low-income households. The rates did rise. But the scheme''s unredeemed deposits fall disproportionately on households that cannot easily return containers, so the second half of that claim is wrong.", "credited_answers": ["The deposit scheme raised recycling rates, but it did so at some cost to low-income households."], "explanation": "Note: two moves, and only one of them is a rejection. The author concedes the first conjunct outright. An answer that rejects both (\"the scheme did not raise recycling rates\") contradicts a claim the author granted.", "category": "Level 4: Compound rebuttals"}, {"order": 36, "prompt": "Critics of the attribution say the underdrawing is inconsistent with the master''s practice and that the panel must therefore be a workshop product. The underdrawing is indeed unusual for him. It does not follow that the panel is a workshop product, since he is documented as varying his preparation on commissions of this scale.", "credited_answers": ["The underdrawing is unusual for the master, but the panel is not necessarily a workshop product."], "explanation": "Concession preserved. Overshoot: \"the underdrawing is consistent with his practice\" (contradicts the concession) or \"the panel is by the master\" (stronger than the author''s point).", "category": "Level 4: Compound rebuttals"}, {"order": 37, "prompt": "A common view holds that the treaty text was drafted in Latin and that the vernacular version is a later translation. The Latin is certainly the older of the two surviving copies. But the vernacular carries two clauses absent from the Latin, which a translator would have had no source for.", "credited_answers": ["The Latin copy is older, but the vernacular version is not simply a later translation of it."], "explanation": "An even more precise answer folds in the evidence: the vernacular carries clauses a translator working from the Latin could not have supplied. Note: the author rejects the second claim while granting the first, and the granted claim is *not* the same as the rejected one. Read the conjunction carefully.", "category": "Level 4: Compound rebuttals"}, {"order": 38, "prompt": "The report concludes that the outage began at the substation and that the maintenance crew''s error caused it. The substation was the origin. But the relay had already failed its last two tests, and a relay in that condition trips under load regardless of what a crew does.", "credited_answers": ["The outage began at the substation, but the maintenance crew''s error did not necessarily cause it."], "explanation": "Scope note: \"not necessarily\" rather than \"did not.\" The author''s evidence establishes an alternative sufficient cause, not the crew''s innocence. Overshoot: \"the crew made no error.\"", "category": "Level 4: Compound rebuttals"}, {"order": 39, "prompt": "Some historians maintain that the guild''s decline was caused by the new tariff and that no internal factor contributed. The tariff plainly hurt them. Yet the guild had lost a third of its masters to the city companies before the tariff passed.", "credited_answers": ["The tariff hurt the guild, but internal factors also contributed to its decline."], "explanation": "An even more precise answer folds in the evidence: it had already lost a third of its masters before the tariff passed. Note: the negation of \"no internal factor contributed\" is \"at least one did,\" not \"internal factors caused the decline.\"", "category": "Level 4: Compound rebuttals"}, {"order": 40, "prompt": "It is argued that the drug shortens recovery and that it should therefore be first-line therapy. Recovery was shorter in the treatment arm. But the trial excluded patients with the comorbidity that two-thirds of the eligible population has, so the recommendation outruns the evidence.", "credited_answers": ["The drug shortens recovery in the population studied, but that does not establish it as first-line therapy."], "explanation": "Scope note: \"in the population studied\" is the qualification the author''s objection turns on. Overshoot: \"the drug does not shorten recovery.\"", "category": "Level 4: Compound rebuttals"}, {"order": 41, "prompt": "Commentators claim the exhibition failed because the catalogue was late and that the venue was never a factor. The catalogue was late. But attendance at the same show in a comparable city, with the same delay, ran three times higher.", "credited_answers": ["The catalogue was late, but the venue was a factor in the exhibition''s performance."], "explanation": "An even more precise answer folds in the evidence: attendance ran three times higher for the same show, with the same delay, in a comparable city. Note: the author does not say the catalogue was irrelevant. Only the second claim is rejected.", "category": "Level 4: Compound rebuttals"}, {"order": 42, "prompt": "One school holds that the inscription is a forgery, on the grounds that its letterforms are too regular for the period and that no genuine inscription of the period is cut this deep. The letterforms are regular. But three securely dated inscriptions are cut deeper still, so the second ground fails and the first cannot carry the case alone.", "credited_answers": ["The letterforms are regular, but the depth of the cut is no evidence of forgery, and regularity alone does not establish that the inscription is a forgery."], "explanation": "Note: the hardest item in the bank. Three moves: a concession, a rejected sub-claim, and a judgment about what the surviving ground can support. An answer that says \"the inscription is genuine\" overshoots all three; the author says the case for forgery fails, which is not the same as establishing authenticity.", "category": "Level 4: Compound rebuttals"}]'::jsonb
  ),
  (
    'dumb-it-down',
    'Dumb it Down',
    'Compress the paragraph to its big ideas, in plain words',
    '{"coach": {"drill": "a paragraph-compression drill: the student restates a dense academic paragraph in plain language, keeping every big idea", "rubric": ["The credited answer is a plain-language summary carrying all of the paragraph''s big ideas. The author''s note lists them; check the response against that list.", "Judge coverage and accuracy, never elegance. A blunt, informal summary that carries every big idea is fully correct.", "Technical vocabulary does not need to be preserved. A student who explains a term in their own words has done the exercise correctly.", "Where the paragraph sets a common view against what is actually the case, or sets two camps against each other, both sides and who holds them must survive into the summary."], "partial_rule": "Mark ''partial'' when the summary is accurate but too narrow, carrying some big ideas and missing others, which is the drill''s signature miss. Mark ''incorrect'' when the response only names the topic without saying what the paragraph claims about it, or misstates the paragraph''s point."}, "tagline": "Understand the hard words functionally. Do not preserve them.", "task": "Read the paragraph and tell me what it says in plain language. Keep every big idea and drop everything else.", "rules": ["Your summary has to carry the big ideas. If one goes missing, the summary is too narrow no matter how well written it is.", "Say it in words you would use out loud. Technical vocabulary is there to be understood, not repeated.", "If the paragraph sets up a contrast between what people think and what is actually the case, both halves belong in your answer.", "Where two camps disagree, keep who thinks what. Losing the attribution loses the paragraph.", "Naming the topic is not summarizing the paragraph."]}'::jsonb,
    'free-text',
    '[{"order": 1, "prompt": "Lighthouse keepers are often remembered as solitary romantics who chose isolation for its own sake. In practice, most keepers were practical tradespeople managing an industrial workplace. A single station required constant fuel measurement, lens polishing, logbook entries, and equipment repair on a strict schedule set by the lighthouse authority. Keepers who missed a lighting time or let a lens cloud over faced fines and dismissal. The job attracted people who wanted steady government wages and housing, not poets seeking solitude. The isolation was a cost of the work, not its attraction.", "credited_answers": ["Lighthouse keepers were not romantic loners but practical workers running a demanding industrial job, and the isolation was a downside of the work rather than the reason they chose it."], "explanation": "The big ideas your summary has to carry: (1) popular image: solitary romantics · (2) reality: tradespeople in a regulated industrial job · (3) isolation was a cost, not the appeal. Named traps: Too narrow: \"Keepers had to polish lenses and keep logbooks.\" Topic-only: \"Lighthouse keeping was a hard job.\"", "category": "Tier 1: One clear contrast, plain vocabulary"}, {"order": 2, "prompt": "Municipal fountains in nineteenth-century cities are commonly described as decorative luxuries commissioned by vain city councils. That description misses their sanitary purpose. Before household plumbing became widespread, public fountains were often the only reliable source of clean drinking water in crowded districts, and their placement closely tracked outbreaks of waterborne disease. Councils built them where wells had been contaminated, and engineers designed the basins to keep animals and washing away from the drinking spouts. The ornament was real, but it decorated a piece of public health infrastructure.", "credited_answers": ["Nineteenth-century public fountains were not just decoration; they were public health infrastructure that supplied clean drinking water to districts where wells were contaminated."], "explanation": "The big ideas your summary has to carry: (1) common view: decorative vanity projects · (2) actual function: clean water / disease prevention · (3) design and placement served the sanitary purpose. Named traps: Too narrow: \"Fountain basins kept animals away from the spouts.\" Topic-only: \"Cities built many fountains in the 1800s.\"", "category": "Tier 1: One clear contrast, plain vocabulary"}, {"order": 3, "prompt": "The switchboard operators who connected early telephone calls are sometimes dismissed as unskilled labor eliminated by obvious automation. The record suggests otherwise. Operators memorized hundreds of line assignments, diagnosed faults by ear, and managed emergency traffic during storms and fires when call volume spiked beyond anything the equipment was designed for. Telephone companies resisted automatic exchanges for decades partly because operators absorbed failures the machinery could not. Automation succeeded only after engineers redesigned the network around the judgment calls operators had quietly been making all along.", "credited_answers": ["Early switchboard operators were skilled workers whose judgment held the phone network together, and automation only replaced them once engineers rebuilt the system around the work they had been doing."], "explanation": "The big ideas your summary has to carry: (1) dismissive view: unskilled, obviously automatable · (2) reality: skilled diagnosis and emergency management · (3) automation required redesigning around their judgment. Named traps: Too narrow: \"Operators memorized hundreds of line assignments.\" Topic-only: \"Telephones used to need human operators.\"", "category": "Tier 1: One clear contrast, plain vocabulary"}, {"order": 4, "prompt": "Hand-copied recipe books passed between households are easy to read as quaint domestic keepsakes. Historians of food increasingly treat them as working technical documents. Copyists corrected quantities that failed, noted substitutions for scarce ingredients, and recorded which preparations preserved food safely through winter. Because the books moved between kitchens with the people who used them, their marginal notes preserve a record of trial, error, and adaptation that printed cookbooks of the period, written for idealized kitchens, deliberately smoothed over.", "credited_answers": ["Hand-copied recipe books were not just keepsakes but working technical records whose corrections and notes captured real kitchen experimentation that printed cookbooks left out."], "explanation": "The big ideas your summary has to carry: (1) quaint-keepsake view · (2) reality: corrected, tested technical documents · (3) they preserve trial-and-error evidence printed books smoothed over. Named traps: Too narrow: \"People wrote substitutions in the margins.\" Topic-only: \"Old recipe books are historically interesting.\"", "category": "Tier 1: One clear contrast, plain vocabulary"}, {"order": 5, "prompt": "The physician credited with early anesthesia records is often celebrated simply for using ether during surgery. Her more lasting contribution was procedural. She insisted that every administration be logged with the patient''s weight, the dose, the time to unconsciousness, and the time to waking, and she refused to call any outcome a success until the numbers were recorded. Colleagues found the bookkeeping tedious, yet those logs made dosage predictable, turned anesthesia from a gamble into a calculable procedure, and became the model for the clinical record-keeping that modern surgical safety depends on.", "credited_answers": ["Her real contribution was not just using ether but insisting on systematic dose records, which turned anesthesia into a predictable procedure and modeled modern clinical record-keeping."], "explanation": "The big ideas your summary has to carry: (1) remembered for: using ether · (2) actual leap: mandatory quantified logging · (3) consequence: predictable dosing and the template for clinical records. Named traps: Too narrow: \"She logged patients'' weights and doses.\" Topic-only: \"She was an early anesthesia pioneer.\"", "category": "Tier 2: A figure''s conceptual leap, mild jargon"}, {"order": 6, "prompt": "The cartographer who first mapped the deep Atlantic seafloor is usually mentioned for the maps themselves. Her conceptual advance was treating the ocean floor as terrain at all. Contemporaries assumed the deep sea was a featureless plain and plotted soundings as isolated numbers. She interpolated between soundings the way land surveyors did between hilltops, drew ridges and valleys where no one had authorized them, and in doing so revealed a continuous mountain range running down the ocean''s center. The maps mattered because the assumption behind them changed what the numbers could mean.", "credited_answers": ["Her breakthrough was treating the seafloor as real terrain rather than a featureless plain, which let scattered depth measurements reveal a continuous mid-ocean mountain range."], "explanation": "The big ideas your summary has to carry: (1) known for: the maps · (2) conceptual leap: seafloor as terrain, interpolating like a land surveyor · (3) result: the mid-ocean ridge became visible. Named traps: Too narrow: \"She drew ridges between soundings.\" Topic-only: \"She made important maps of the Atlantic.\"", "category": "Tier 2: A figure''s conceptual leap, mild jargon"}, {"order": 7, "prompt": "The economist who reorganized a national postal system is remembered for cutting delivery times, but the deeper idea was about pricing. Before the reform, postage was charged by distance and collected from the recipient, which made every letter a negotiation and left the system drowning in refused mail. He proposed a single low prepaid rate for any destination in the country, reasoning that the cost of handling a letter lay in sorting and delivery labor, not in miles traveled. Prepayment converted mail from a per-transaction haggle into cheap standardized infrastructure, and volume grew enough to pay for the reform many times over.", "credited_answers": ["His key insight was that mail should be prepaid at one flat rate because handling, not distance, drove the cost, which turned the post into cheap standardized infrastructure and massively grew volume."], "explanation": "The big ideas your summary has to carry: (1) remembered for: faster delivery · (2) real idea: flat prepaid pricing based on handling cost · (3) consequence: standardization and volume growth. Named traps: Too narrow: \"Recipients used to refuse their mail.\" Topic-only: \"He reformed the postal system.\"", "category": "Tier 2: A figure''s conceptual leap, mild jargon"}, {"order": 8, "prompt": "The programmer who wrote an early machine translation demonstration is often cited for the demonstration''s failure. Her working notes point somewhere more interesting. She concluded that translation failed not because dictionaries were too small but because meaning depends on context that sentences do not contain, and she proposed that any successful system would need to store and consult structured knowledge about the world. That diagnosis, largely ignored at the time, anticipated the direction the field eventually took decades later, when translation systems began to succeed by modeling context rather than by enlarging word lists.", "credited_answers": ["Her lasting contribution was diagnosing that machine translation fails without contextual world knowledge, not because dictionaries are too small, a conclusion the field only later proved right."], "explanation": "The big ideas your summary has to carry: (1) cited for: a failed demo · (2) diagnosis: meaning needs context beyond the sentence · (3) anticipation: the field later succeeded by modeling context. Named traps: Too narrow: \"Her demonstration did not work.\" Topic-only: \"Early machine translation was difficult.\"", "category": "Tier 2: A figure''s conceptual leap, mild jargon"}, {"order": 9, "prompt": "Some urban planners argue that widening congested roads is self-defeating because added capacity attracts new drivers until congestion returns to its old level. Others respond that this induced traffic is not waste but demand that was always there, suppressed by gridlock, and that the new trips represent real economic activity. The disagreement is therefore not about whether widened roads fill up. Both sides accept that they do. It is about whether the filling should be counted as a failure of congestion relief or as a success in serving trips the old road was silently rationing.", "credited_answers": ["Both camps agree widened roads fill back up; they disagree about whether that returning traffic proves widening fails or shows it is serving real demand the congestion had been suppressing."], "explanation": "The big ideas your summary has to carry: (1) camp one: induced traffic makes widening self-defeating · (2) camp two: the new trips are real suppressed demand · (3) shared ground: roads do fill up; the dispute is how to count it. Named traps: Too narrow: \"New lanes attract more drivers.\" Topic-only: \"Planners disagree about road widening.\" (Misses that the disagreement is about interpretation, not the facts.)", "category": "Tier 3: Two camps, and the summary must keep who-thinks-what"}, {"order": 10, "prompt": "Conservators disagree about restoring faded murals. One school holds that every repainted stroke, however faithful, replaces the artist''s hand with the restorer''s and should be refused on principle; better a ghost of the original than a confident forgery. The opposing school answers that murals were made to be legible public statements, and that leaving one illegible betrays the work''s purpose more deeply than careful inpainting ever could. Underneath the technical debate sits a disagreement about what the object actually is: a physical relic of the artist''s touch, or a public image whose meaning requires visibility.", "credited_answers": ["Mural restorers split between refusing repainting to preserve the artist''s actual hand and repainting to preserve the mural''s legible public message, a dispute over whether the object is a relic or an image."], "explanation": "The big ideas your summary has to carry: (1) camp one: never repaint, the touch is the work · (2) camp two: repaint, legibility is the work · (3) the real disagreement: what kind of object a mural is. Named traps: Too narrow: \"Some restorers use inpainting on faded murals.\" Topic-only: \"Experts disagree about restoration.\"", "category": "Tier 3: Two camps, and the summary must keep who-thinks-what"}, {"order": 11, "prompt": "When excavations uncover large storehouses beside ancient temples, one group of archaeologists reads them as evidence of centralized command economies in which priests collected and rationed the harvest. Skeptics counter that the same buildings are equally consistent with voluntary festival provisioning, insurance stockpiles against famine, or market warehousing, and that only the storerooms'' scale has been demonstrated, not their governance. The skeptics do not deny that temples stored grain. Their claim is that storage capacity by itself cannot distinguish between an economy run by decree and one that merely gathered in the same buildings.", "credited_answers": ["Everyone agrees ancient temples stored large amounts of grain; the dispute is whether big storehouses prove a centrally commanded economy or are equally consistent with voluntary and market uses."], "explanation": "The big ideas your summary has to carry: (1) camp one: storehouses show priestly command economies · (2) camp two: capacity alone cannot show governance · (3) shared ground: the storage itself is real. Named traps: Too narrow: \"Archaeologists found storerooms next to temples.\" Topic-only: \"Scholars debate ancient economies.\"", "category": "Tier 3: Two camps, and the summary must keep who-thinks-what"}, {"order": 12, "prompt": "Among linguists who study dying languages, documentation specialists argue that scarce funding should record elderly fluent speakers before their knowledge disappears, since a recorded language can in principle be revived later, while an unrecorded one cannot. Revitalization specialists reply that languages live only in daily use, that archives full of unspoken recordings are cemeteries rather than seed banks, and that the same money spent on children''s immersion programs keeps the language alive without needing revival at all. Each side accuses the other of planning for the wrong future: one for a future where the language has died, the other for a future where it never does.", "credited_answers": ["Documentation linguists want scarce funds spent recording elderly speakers so the language could someday be revived, while revitalization linguists want the money spent keeping children speaking it now, each side planning for a different future."], "explanation": "The big ideas your summary has to carry: (1) camp one: record before knowledge dies; archives enable revival · (2) camp two: fund immersion; use is life, archives are cemeteries · (3) the frame: they disagree about which future to plan for. Named traps: Too narrow: \"Linguists record elderly native speakers.\" Topic-only: \"Experts disagree about saving endangered languages.\"", "category": "Tier 3: Two camps, and the summary must keep who-thinks-what"}, {"order": 13, "prompt": "Estimates of historical famine mortality long depended on chronicles and tax rolls, sources that survive unevenly and that officials had reasons to distort. Demographers have begun instead to read the famines out of later census structure: a birth cohort gutted by starvation and delayed marriages leaves a permanent notch that moves up the age pyramid for a century, and its depth can be measured decades after the event by anyone with reliable census tables. The method does not date famines more precisely than the chronicles do, but it converts their severity from a matter of testimony into a matter of measurement.", "credited_answers": ["Demographers are shifting famine studies from trusting distorted chronicles to measuring the lasting notches famines leave in later census age structures, turning severity from testimony into measurement."], "explanation": "The big ideas your summary has to carry: (1) old method: chronicles and tax rolls, uneven and distorted · (2) new method: cohort notches in census pyramids · (3) the shift''s meaning: severity becomes measurable, though dating does not improve. Named traps: Too narrow: \"Famines leave notches in age pyramids.\" Topic-only: \"Historians study old famines.\"", "category": "Tier 4: The main point is a shift in method or framing, technical vocabulary"}, {"order": 14, "prompt": "Attribution of unsigned paintings once rested on connoisseurship, the trained eye of specialists who judged brushwork and composition and whose verdicts were difficult to challenge because the evidence was, in the end, their own perception. Laboratories have altered the terrain. Pigment chemistry can rule out dates, canvas weave matching can tie pictures to a workshop''s bolt of cloth, and imaging reveals underdrawings that copyists rarely reproduce. The techniques rarely name a painter outright. What they do is redistribute authority: a connoisseur''s attribution must now survive material tests that anyone can repeat, and the eye has become one instrument among several rather than the court of final appeal.", "credited_answers": ["Scientific analysis has shifted painting attribution from resting on connoisseurs'' unchallengeable trained eyes to requiring verdicts that survive repeatable material tests, demoting the eye to one instrument among several."], "explanation": "The big ideas your summary has to carry: (1) old regime: the connoisseur''s perception as final authority · (2) new tools: pigment dating, weave matching, imaging · (3) the shift: authority redistributed to repeatable tests; the eye demoted, not replaced. Named traps: Too narrow: \"Labs can match canvas weave to a workshop.\" Topic-only: \"Science helps identify paintings.\"", "category": "Tier 4: The main point is a shift in method or framing, technical vocabulary"}, {"order": 15, "prompt": "Wildlife censuses once counted what observers could see: animals flushed from transects, nests spotted from aircraft, tracks crossing survey lines. Sampling environmental DNA has begun to invert the logic. A liter of stream water carries genetic traces of everything that shed cells upstream, so presence is now inferred from molecules rather than encounters, and absence of a species becomes a statement about detection thresholds rather than about empty habitat. The change forces a redefinition of the census itself: fieldworkers no longer ask how many animals they found, but how much signal a landscape produces and what fraction of it their methods can recover.", "credited_answers": ["Environmental DNA is changing wildlife censuses from counting animals observers encounter to inferring presence from genetic traces in water, redefining surveys as questions about recoverable signal rather than sightings."], "explanation": "The big ideas your summary has to carry: (1) old method: visual encounter counts · (2) new method: molecular traces in environmental samples · (3) the redefinition: from \"how many did we find\" to \"how much signal can we recover\"; absence becomes a threshold claim. Named traps: Too narrow: \"Stream water contains animal DNA.\" Topic-only: \"There are new ways to count wildlife.\"", "category": "Tier 4: The main point is a shift in method or framing, technical vocabulary"}, {"order": 16, "prompt": "The dating of early metalworking sites long leaned on typology: arrange the recovered tools by shape, assume simple forms precede refined ones, and read the sequence as time. Radiometric methods embarrassed that assumption at site after site, showing refined and crude forms in use simultaneously, sometimes in the same workshop. The response has not been to abandon typology but to reassign its job. Tool shapes are now read as evidence of workshop tradition, trade connection, and intended market, while the calendar is left to laboratory dates. The shapes, in other words, stopped telling time and started telling everything else.", "credited_answers": ["Radiometric dating showed that tool shapes do not track time, so archaeologists reassigned typology from dating sites to revealing workshop traditions, trade, and markets, leaving chronology to the lab."], "explanation": "The big ideas your summary has to carry: (1) old assumption: simple-to-refined shape sequence equals time · (2) the embarrassment: lab dates showed forms coexisting · (3) the reassignment: shapes now evidence tradition/trade/market, not chronology. Named traps: Too narrow: \"Crude and refined tools were used at the same time.\" Topic-only: \"Archaeologists date metalworking sites.\"", "category": "Tier 4: The main point is a shift in method or framing, technical vocabulary"}, {"order": 17, "prompt": "Courts assessing eyewitness identifications historically asked whether the witness was confident, attentive, and honest, treating memory as a recording whose quality those virtues guaranteed. Decades of controlled experiments reframed the question by showing that identification accuracy depends heavily on conditions no witness controls: lighting, distance, stress, the composition of the lineup, and the feedback given afterward. The experiments do not show that eyewitnesses are generally wrong, and confident witnesses are still right more often than hesitant ones. What the research undermines is the inference from sincerity to accuracy, and courts have slowly begun to instruct juries on viewing conditions rather than character.", "credited_answers": ["Research reframed eyewitness reliability as a matter of viewing and lineup conditions rather than witness character, and while witnesses are not generally wrong, sincerity no longer counts as proof of accuracy."], "explanation": "The big ideas your summary has to carry: (1) old frame: confidence and honesty guarantee memory · (2) reframe: accuracy tracks conditions outside the witness''s control · (3) retained concession: witnesses are often right; what falls is the sincerity-to-accuracy inference. Named traps: Too narrow: \"Lineup composition affects identifications.\" Topic-only: \"Eyewitness testimony can be unreliable.\" (Overshoots by dropping the concession.)", "category": "Tier 5: Shift plus a retained concession the summary must keep"}, {"order": 18, "prompt": "Nutrition guidance once ranked dietary fats by their chemistry, condemning saturated varieties wholesale and promoting substitutes with more favorable laboratory profiles. Long-term population studies complicated the ranking by showing that health outcomes track what replaces a discarded fat: swapping it for refined starches yields no benefit, while swapping it for certain plant oils does. The chemistry was not wrong, and some substitutions really are improvements. The revision is in the unit of advice. Foods and their replacements, not molecules in isolation, have become the thing guidance is written about, because a nutrient''s effect proved inseparable from what fills its place at the table.", "credited_answers": ["Nutrition advice shifted from ranking fat molecules to evaluating whole substitutions, because outcomes depend on what replaces a discarded fat, even though the underlying chemistry and some swaps remain valid."], "explanation": "The big ideas your summary has to carry: (1) old unit: molecule-level rankings · (2) complication: outcomes track the replacement, not the removal · (3) retained concession: chemistry holds and some substitutions genuinely help; the change is the unit of advice. Named traps: Too narrow: \"Replacing fat with refined starch does not help.\" Topic-only: \"Nutrition science keeps changing its mind.\" (The cynical overshoot; the paragraph says the opposite.)", "category": "Tier 5: Shift plus a retained concession the summary must keep"}, {"order": 19, "prompt": "Flood control on large rivers was for a century an engineering contest: raise the levees, straighten the channel, move the water through faster. Repeated levee failures shifted the field toward a different accounting, in which the cheapest place to put floodwater is often a farm field purchased for occasional inundation rather than a wall built to exclude the water entirely. Engineered defenses still protect cities, and no one proposes removing them. The change is in what counts as infrastructure: acquired floodplain, wetland easements, and setback levees now appear in project budgets alongside concrete, because the failures showed that exclusion alone was purchasing risk at compound interest.", "credited_answers": ["After repeated levee failures, flood control expanded from pure exclusion engineering to budgeting land that can safely flood as infrastructure, while hard defenses still protect cities."], "explanation": "The big ideas your summary has to carry: (1) old contest: higher levees, faster channels · (2) shift: purchased floodplain and setbacks count as infrastructure · (3) retained concession: engineered defenses remain; exclusion alone compounded risk. Named traps: Too narrow: \"Some farm fields are bought to hold floodwater.\" Topic-only: \"Levees sometimes fail.\"", "category": "Tier 5: Shift plus a retained concession the summary must keep"}, {"order": 20, "prompt": "Histories of literacy long measured it by signatures: count who could sign a parish register, and map reading across a society. Scholars now emphasize that signing was taught after reading and separately from it, so signature counts systematically undercount readers, capturing mostly those schooled long enough to write, and excluding the many taught to read scripture at home who never held a pen. Signature evidence has not been discarded; nothing else survives at comparable scale, and its trends over time remain informative. What changed is the claim it supports: a floor under past literacy rather than an estimate of it.", "credited_answers": ["Because writing was taught after reading, signature counts undercount past readers, so historians now treat them as a floor under literacy rather than an estimate, while still relying on their trends."], "explanation": "The big ideas your summary has to carry: (1) old measure: signatures as literacy · (2) flaw: reading preceded writing, so readers are missed · (3) retained concession: the evidence survives at unmatched scale and still shows trends; its claim is downgraded to a floor. Named traps: Too narrow: \"Many people could read but not sign.\" Topic-only: \"Measuring historical literacy is hard.\"", "category": "Tier 5: Shift plus a retained concession the summary must keep"}, {"order": 21, "prompt": "Early quantitative studies of scientific careers measured productivity by publication counts and found that a small fraction of researchers produced most of the papers, a result read for decades as evidence of rare individual talent. Later work complicated both the measure and the reading. Counting papers weights fields unequally, since publication rates are set by disciplinary custom rather than effort, and the concentration itself proved to be manufactured partly by institutions: early access to equipment, students, and funding compounds, so that small initial differences in opportunity grow into large final differences in output. Talent has not been dismissed as a factor. The revision is subtler: concentration of output is now treated as a joint product of ability and cumulative institutional advantage, and the measure that revealed it is no longer trusted to compare across fields.", "credited_answers": ["The finding that a few scientists produce most papers is now explained as talent compounded by accumulating institutional advantage rather than rare ability alone, and raw publication counts are no longer trusted across fields."], "explanation": "The big ideas your summary has to carry: (1) original finding and reading: concentrated output proves rare talent · (2) first correction: the measure is field-biased · (3) second correction: institutions compound small early advantages · (4) retained role for talent in a joint explanation. Named traps: Too narrow: \"Some fields publish more papers than others.\" Topic-only: \"A few scientists write most papers.\" (States the finding while missing the reinterpretation, which is the point.)", "category": "Tier 6: Double contrast, abstract subject, maximum load"}, {"order": 22, "prompt": "Classic accounts of trade before state coinage assumed barter, with money arising to solve the awkwardness of matching wants. Records from early cities support a different sequence: temple and palace bookkeepers denominated debts in standard quantities of grain and silver long before coins circulated, and most exchange took the form of credit entries against future harvests. Coinage, when it arrived, served less to enable trade than to let rulers pay soldiers and collect taxes in a medium they controlled. Barter was real, but it flourished mainly between strangers and at frontiers, where no ledger bound the parties. On this account money''s origin is administrative rather than commercial, and the barter story survives as a special case rather than a beginning.", "credited_answers": ["Evidence from early cities suggests money began as administrative accounting for debts, with coins serving state payment and taxation, while barter was a frontier special case rather than the origin of trade."], "explanation": "The big ideas your summary has to carry: (1) classic story: barter first, money as its fix · (2) documented sequence: ledger credit in standard units preceded coins · (3) coinage''s actual role: state payment and taxation · (4) barter retained as a real but special case among strangers. Named traps: Too narrow: \"Bookkeepers recorded debts in grain and silver.\" Topic-only: \"Money has a long history.\"", "category": "Tier 6: Double contrast, abstract subject, maximum load"}, {"order": 23, "prompt": "Sleep research first treated the sleeping brain as idle, then, after recordings revealed intense nocturnal activity, as busy with a single master task, with memory consolidation the leading candidate. Both frames now look too simple. The sleeping brain runs distinct programs in different stages, and interventions that disrupt one stage impair some functions while leaving others intact: slow-wave disruption degrades factual recall but spares motor learning, while dream-stage suppression does something closer to the reverse. Consolidation has not been dethroned as one genuine function among several. What has been abandoned is the search for the purpose of sleep, in favor of mapping which stage serves which function, on the view that sleep is a schedule of maintenance operations rather than a single process with a single point.", "credited_answers": ["Sleep science has moved from asking what sleep is for to mapping which sleep stage serves which function, treating sleep as a schedule of distinct maintenance programs, with memory consolidation kept as one function among several."], "explanation": "The big ideas your summary has to carry: (1) frame one: idle brain · (2) frame two: one master task (consolidation) · (3) current view: stage-specific functions shown by selective disruption · (4) retained: consolidation is real but not the single purpose; the single-purpose question itself is abandoned. Named traps: Too narrow: \"Disrupting slow-wave sleep hurts factual recall.\" Topic-only: \"Scientists study why we sleep.\"", "category": "Tier 6: Double contrast, abstract subject, maximum load"}, {"order": 24, "prompt": "Antitrust doctrine spent half a century anchored to a single question, whether conduct raised prices for consumers, a standard prized for making enforcement predictable and economic rather than political. Critics now press two distinct objections that are often conflated. The first accepts the consumer-price frame and argues the measurements were done badly, since quality degradation, data extraction, and forgone innovation are price-like harms the cases ignored. The second rejects the frame itself, holding that concentrated private power injures suppliers, workers, and the openness of markets in ways no consumer metric captures. Defenders answer that the first critique is absorbable and the second is a mandate for judges to weigh incommensurable values without a scale. The live dispute is therefore not whether the old standard missed harms. It is whether the remedy is better measurement inside the frame or replacement of the frame, at the cost of the predictability that made the standard attractive.", "credited_answers": ["Everyone now grants the consumer-price standard missed real harms; the fight is between fixing its measurements within the frame and replacing the frame to reach power-based harms, at the price of the predictability that justified it."], "explanation": "The big ideas your summary has to carry: (1) old anchor: consumer prices, prized for predictability · (2) critique one: right frame, bad measurement (quality, data, innovation) · (3) critique two: wrong frame, power harms beyond consumers · (4) defenders'' reply and the real dispute: repair vs replace, with predictability as the stake. Named traps: Too narrow: \"Antitrust cases ignored data extraction.\" Topic-only: \"People disagree about antitrust law.\" (Also trap: presenting the two critiques as one, which the paragraph explicitly warns against conflating.)", "category": "Tier 6: Double contrast, abstract subject, maximum load"}]'::jsonb
